insert into public.questoes (numero, parte, capitulo, pergunta, resposta, status)
values
  (1, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Que é Deus?', 'Deus é a inteligência suprema, causa primária de todas as coisas.', 'rascunho'),
  (2, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Que se deve entender por infinito?', 'O que não tem começo nem fim: o desconhecido; tudo o que é desconhecido é infinito.', 'rascunho'),
  (3, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Poder-se-ia dizer que Deus é o infinito?', 'Definição incompleta. Pobreza da linguagem humana, insuficiente para definir o que está acima da linguagem dos homens." Deus é infinito em suas perfeições, mas o infinito é uma abstração. Dizer que Deus é o infinito é tomar o atributo de uma coisa pela coisa mesma, é definir uma coisa que não está conhecida por uma outra que não o está mais do que a primeira.', 'rascunho'),
  (4, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Onde se pode encontrar a prova da existência de Deus?', 'Num axioma que aplicais às vossas ciências. Não há efeito sem causa. Procurai a causa de tudo o que não é obra do homem e a vossa razão responderá." Para crer-se em Deus, basta se lance o olhar sobre as obras da Criação. O Universo existe, logo tem uma causa. Duvidar da existência de Deus é negar que todo efeito tem uma causa e avançar que o nada pôde fazer alguma coisa. 3 O texto colocado entre aspas, em seguida às perguntas, é a resposta que os Espíritos deram. Para destacar as notas e explicações aditadas pelo autor, quando haja possibilidade de serem confundidas com o texto da resposta, empregou-se um outro tipo menor. Quando formam capítulos inteiros, sem ser possível a confusão, o mesmo tipo usado para as perguntas e respostas foi o empregado. 42 – Allan Kar dec', 'rascunho'),
  (5, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Que dedução se pode tirar do sentimento instintivo, que todos os homens trazem em si, da existência de Deus?', 'A de que Deus existe; pois, donde lhes viria esse sentimento, se não tivesse uma base? É ainda uma conseqüência do princípio — não há efeito sem causa.', 'rascunho'),
  (6, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'O sentimento íntimo que temos da existência de Deus não poderia ser fruto da educação, resultado de idéias adquiridas?', 'Se assim fosse, por que existiria nos vossos selvagens esse sentimento?" Se o sentimento da existência de um ser supremo fosse tão-somente produto de um ensino, não seria universal e não existiria senão nos que houvessem podido receber esse ensino, conforme se dá com as noções científicas.', 'rascunho'),
  (7, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Poder-se-ia achar nas propriedades íntimas da matéria a causa primária da formação das coisas?', 'Mas, então, qual seria a causa dessas propriedades? É indispensável sempre uma causa primária." Atribuir a formação primária das coisas às propriedades íntimas da matéria seria tomar o efeito pela causa, porquanto essas propriedades são, também elas, um efeito que há de ter uma causa.', 'rascunho'),
  (8, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Que se deve pensar da opinião dos que atribuem a formação primária a uma combinação fortuita da matéria, ou, por outra, ao acaso?', 'Outro absurdo! Que homem de bom-senso pode considerar o acaso um ser inteligente? E, demais, que é o acaso? Nada." A harmonia existente no mecanismo do Universo patenteia combinações e desígnios determinados e, por isso mesmo, revela um poder inteligente. Atribuir a formação primária ao acaso é insensatez, pois que o acaso é cego e não pode produzir os efeitos que a inteligência produz. Um acaso inteligente já não seria acaso.', 'rascunho'),
  (9, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Em que é que, na causa primária, se revela uma inteligência suprema e superior a todas as inteligências?', 'Tendes um provérbio que diz: Pela obra se reconhece o autor. Pois bem! Vede a obra e procurai o autor. O orgulho é que gera a incredulidade. O homem orgulhoso nada admite acima de si. Por isso é que ele se denomina a si mesmo de espírito forte. Pobre ser, que um sopro de Deus pode abater!" Do poder de uma inteligência se julga pelas suas obras. Não podendo nenhum ser humano criar o que a Natureza produz, a causa primária é, conseguintemente, uma inteligência superior à Humanidade. Quaisquer que sejam os prodígios que a inteligência humana tenha operado, ela própria tem uma causa e, quanto maior for o que opere, tanto maior há de ser a causa primária. Aquela inteligência superior é que é a causa primária de todas as coisas, seja qual for o nome que lhe dêem.', 'rascunho'),
  (10, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Pode o homem compreender a natureza íntima de Deus?', 'Não; falta-lhe para isso o sentido.', 'rascunho'),
  (11, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Será dado um dia ao homem compreender o mistério da Divindade?', 'Quando não mais tiver o espírito obscurecido pela matéria. Quando, pela sua perfeição, se houver aproximado de Deus, ele o verá e compreenderá." A inferioridade das faculdades do homem não lhe permite compreender a natureza íntima de Deus. Na infância da Humanidade, o homem o confunde muitas vezes com a criatura, cujas imperfeições lhe atribui; mas, à medida que nele se desenvolve o senso moral, seu pensamento penetra melhor no âmago das coisas; então, faz idéia mais justa da Divindade e, ainda que sempre incompleta, mais conforme à sã razão.', 'rascunho'),
  (12, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Embora não possamos compreender a natureza íntima de Deus, podemos formar idéia de algumas de Suas perfeições?', 'De algumas, sim. O homem as compreende melhor à proporção que se eleva acima da matéria. Entrevê-as pelo pensamento.', 'rascunho'),
  (13, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Quando dizemos que Deus é eterno, infinito, imutável, imaterial, único, onipotente, soberanamente justo e bom, temos idéia completa de seus atributos?', 'Do vosso ponto de vista, sim, porque credes abranger tudo. Sabei, porém, que há coisas que estão acima da inteligência do homem mais inteligente, as quais a vossa linguagem, restrita às vossas idéias e sensações, não tem meios de exprimir. A razão, com efeito, vos diz que Deus deve possuir em grau supremo essas perfeições, porquanto, se uma lhe faltasse, ou não fosse infinita, já ele não seria superior a tudo, não seria, por conseguinte, Deus. Para estar acima de todas as coisas, Deus tem que se achar isento de qualquer vicissitude e de qualquer das imperfeições que a imaginação possa conceber." Deus é eterno. Se tivesse tido princípio, teria saído do nada, ou, então, também teria sido criado, por um ser anterior. É assim que, de degrau em degrau, remontamos ao infinito e à eternidade. É imutável. Se estivesse sujeito a mudanças, as leis que regem o Universo nenhuma estabilidade teriam. É imaterial. Quer isto dizer que a sua natureza difere de tudo o que chamamos matéria. De outro modo, ele não seria imutável, porque estaria sujeito às transformações da matéria. É único. Se muitos Deuses houvesse, não haveria unidade de vistas, nem unidade de poder na ordenação do Universo. É onipotente. Ele o é, porque é único. Se não dispusesse do soberano poder, algo haveria mais poderoso ou tão poderoso quanto ele, que então não teria feito todas as coisas. As que não houvesse feito seriam obra de outro Deus. É soberanamente justo e bom. A sabedoria providencial das leis divinas se revela, assim nas mais pequeninas coisas, como nas maiores, e essa sabedoria não permite se duvide nem da justiça nem da bondade de Deus. 44 – Allan Kar dec', 'rascunho'),
  (14, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Deus é um ser distinto, ou será, como opinam alguns, a resultante de todas as forças e de todas as inteligências do Universo reunidas?', 'Se fosse assim, Deus não existiria, porquanto seria efeito e não causa. Ele não pode ser ao mesmo tempo uma e outra coisa." "Deus existe; disso não podeis duvidar e é o essencial. Crede-me, não vades além. Não vos percais num labirinto donde não lograríeis sair. Isso não vos tornaria melhores, antes um pouco mais orgulhosos, pois que acreditaríeis saber, quando na realidade nada saberíeis. Deixai, conseguintemente, de lado todos esses sistemas; tendes bastantes coisas que vos tocam mais de perto, a começar por vós mesmos. Estudai as vossas próprias imperfeições, a fim de vos libertardes delas, o que será mais útil do que pretenderdes penetrar no que é impenetrável.', 'rascunho'),
  (15, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Que se deve pensar da opinião segundo a qual todos os corpos da Natureza, todos os seres, todos os globos do Universo seriam partes da Divindade e constituiriam, em conjunto, a própria Divindade, ou, por outra, que se deve pensar da doutrina panteísta?', 'Não podendo fazer-se Deus, o homem quer ao menos ser uma parte de Deus.', 'rascunho'),
  (16, 'Parte Primeira — Das causas primárias', 'Capítulo I — De Deus', 'Pretendem os que professam esta doutrina achar nela a demonstração de alguns dos atributos de Deus: Sendo infinitos os mundos, Deus é, por isso mesmo, infinito; não havendo o vazio, ou o nada em parte alguma, Deus está por toda parte; estando Deus em toda parte, pois que tudo é parte integrante de Deus, ele dá a todos os fenômenos da Natureza uma razão de ser inteligente. Que se pode opor a este raciocínio?', 'A razão. Refleti maduramente e não vos será difícil reconhecer-lhe o absurdo." Esta doutrina faz de Deus um ser material que, embora dotado de suprema inteligência, seria em ponto grande o que somos em ponto pequeno. Ora, transformando-se a matéria incessantemente, Deus, se fosse assim, nenhuma estabilidade teria; achar-se-ia sujeito a todas as vicissitudes, mesmo a todas as necessidades da Humanidade; faltar-lhe-ia um dos atributos essenciais da Divindade: a imutabilidade. Não se podem aliar as propriedades da matéria à idéia de Deus, sem que ele fique rebaixado ante a nossa compreensão e não haverá sutilezas de sofismas que cheguem a resolver o problema da sua natureza íntima. Não sabemos tudo o que ele é, mas sabemos o que ele não pode deixar de ser e o sistema de que tratamos está em contradição com as suas mais essenciais propriedades. Ele confunde o Criador com a criatura, exatamente como o faria quem pretendesse que engenhosa máquina fosse parte integrante do mecânico que a imaginou. A inteligência de Deus se revela em suas obras como a de um pintor no seu quadro; mas, as obras de Deus não são o próprio Deus, como o quadro não é o pintor que o concebeu e executou.', 'rascunho'),
  (17, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'É dado ao homem conhecer o princípio das coisas?', 'Não, Deus não permite que ao homem tudo seja revelado neste mundo.', 'rascunho'),
  (18, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'Penetrará o homem um dia o mistério das coisas que lhe estão ocultas?', 'O véu se levanta a seus olhos, à medida que ele se depura; mas, para compreender certas coisas, são-lhe precisas faculdades que ainda não possui.', 'rascunho'),
  (19, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'Não pode o homem, pelas investigações científicas, penetrar alguns dos segredos da Natureza?', 'A Ciência lhe foi dada para seu adiantamento em todas as coisas; ele, porém, não pode ultrapassar os limites que Deus estabeleceu." Quanto mais consegue o homem penetrar nesses mistérios, tanto maior admiração lhe devem causar o poder e a sabedoria do Criador. Entretanto, seja por orgulho, seja por fraqueza, sua própria inteligência o faz joguete da ilusão. Ele amontoa sistemas sobre sistemas e cada dia que passa lhe mostra quantos erros tomou por verdades e quantas verdades rejeitou como erros. São outras tantas decepções para o seu orgulho.', 'rascunho'),
  (20, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'Dado é ao homem receber, sem ser por meio das investigações da Ciência, comunicações de ordem mais elevada acerca do que lhe escapa ao testemunho dos sentidos?', 'Sim, se o julgar conveniente, Deus pode revelar o que à ciência não é dado apreender." Por essas comunicações é que o homem adquire, dentro de certos limites, o conhecimento do seu passado e do seu futuro. 46 – Allan Kar dec', 'rascunho'),
  (21, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'A matéria existe desde toda a eternidade, como Deus, ou foi criada por ele em dado momento?', 'Só Deus o sabe. Há uma coisa, todavia, que a razão vos deve indicar: é que Deus, modelo de amor e caridade, nunca esteve inativo. Por mais distante que logreis figurar o início de sua ação, podereis concebê-lo ocioso, um momento que seja?', 'rascunho'),
  (22, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'Define-se geralmente a matéria como sendo — o que tem extensão, o que é capaz de nos impressionar os sentidos, o que é impenetrável. São exatas estas definições?', 'Do vosso ponto de vista, elas o são, porque não falais senão do que conheceis. Mas a matéria existe em estados que ignorais. Pode ser, por exemplo, tão etérea e sutil, que nenhuma impressão vos cause aos sentidos. Contudo, é sempre matéria. Para vós, porém, não o seria." a) — Que definição podeis dar da matéria? "A matéria é o laço que prende o espírito; é o instrumento de que este se serve e sobre o qual, ao mesmo tempo, exerce sua ação." Deste ponto de vista, pode dizer-se que a matéria é o agente, o intermediário com o auxílio do qual e sobre o qual atua o espírito.', 'rascunho'),
  (23, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'Que é o espírito?', 'O princípio inteligente do Universo." a) — Qual a natureza íntima do espírito? "Não é fácil analisar o espírito com a vossa linguagem. Para vós, ele nada é, por não ser palpável. Para nós, entretanto, é alguma coisa. Ficai sabendo: coisa nenhuma é o nada e o nada não existe.', 'rascunho'),
  (24, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'É o espírito sinônimo de inteligência?', 'A inteligência é um atributo essencial do espírito. Uma e outro, porém, se confundem num princípio comum, de sorte que, para vós, são a mesma coisa.', 'rascunho'),
  (25, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'O espírito independe da matéria, ou é apenas uma propriedade desta, como as cores o são da luz e o som o é do ar?', 'São distintos uma do outro; mas, a união do espírito e da matéria é necessária para intelectualizar a matéria." a) — Essa união é igualmente necessária para a manifestação do espírito? (Entendemos aqui por espírito o princípio da inteligência, abstração feita das individualidades que por esse nome se designam.) "É necessária a vós outros, porque não tendes organização apta a perceber o espírito sem a matéria. A isto não são apropriados os vossos sentidos.', 'rascunho'),
  (26, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'Poder-se-á conceber o espírito sem a matéria e a matéria sem o espírito?', 'Pode-se, é fora de dúvida, pelo pensamento.', 'rascunho'),
  (27, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'Há então dois elementos gerais do Universo: a matéria e o espírito?', 'Sim e acima de tudo Deus, o criador, o pai de todas as coisas. Deus, espírito e matéria constituem o princípio de tudo o que existe, a trindade universal. Mas, ao elemento material se tem que juntar o fluido universal, que desempenha o papel de intermediário entre o espírito e a matéria propriamente dita, por demais grosseira para que o espírito possa exercer ação sobre ela. Embora, de certo ponto de vista, seja lícito classificá-lo com o elemento material, ele se distingue deste por propriedades especiais. Se o fluido universal fosse positivamente matéria, razão não haveria para que também o espírito não o fosse. Está colocado entre o espírito e a matéria; é fluido, como a matéria é matéria, e suscetível, pelas suas inumeráveis combinações com esta e sob a ação do espírito, de produzir a infinita variedade das coisas de que apenas conheceis uma parte mínima. Esse fluido universal, ou primitivo, ou elementar, sendo o agente de que o espírito se utiliza, é o princípio sem o qual a matéria estaria em perpétuo estado de divisão e nunca adquiriria as qualidades que a gravidade lhe dá." a) — Esse fluido será o que designamos pelo nome de eletricidade? "Dissemos que ele é suscetível de inúmeras combinações. O que chamais fluido elétrico, fluido magnético, são modificações do fluido universal, que não é, propriamente falando, senão matéria mais perfeita, mais sutil e que se pode considerar independente.', 'rascunho'),
  (28, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'Pois que o espírito é, em si, alguma coisa, não seria mais exato e menos sujeito a confusão dar aos dois elementos gerais as designações de — matéria inerte e matéria inteligente?', 'As palavras pouco nos importam. Compete-vos a vós formular a vossa linguagem de maneira a vos entenderdes. As vossas controvérsias provêm, quase sempre, de não vos entenderdes acerca dos termos que empregais, por ser incompleta a vossa linguagem para exprimir o que não vos fere os sentidos." Um fato patente domina todas as hipóteses: vemos matéria destituída de inteligência e vemos um princípio inteligente que independe da matéria. A origem e a conexão destas duas coisas nos são desconhecidas. Se promanam ou não de uma só fonte; se há pontos de contacto entre ambas; se a inteligência tem existência própria, ou se é uma propriedade, um efeito; se é mesmo, conforme à opinião de alguns, uma emanação da Divindade, ignoramos. Elas se nos mostram como sendo distintas; daí o considerarmo-las formando os dois princípios constitutivos do Universo. Vemos acima de tudo isso uma inteligência que domina todas as outras, que as governa, que se distingue delas por atributos essenciais. A essa inteligência suprema é que chamamos Deus. 48 – Allan Kar dec', 'rascunho'),
  (29, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'A ponderabilidade é um atributo essencial da matéria?', 'Da matéria como a entendeis, sim; não, porém, da matéria considerada como fluido universal. A matéria etérea e sutil que constitui esse fluido vos é imponderável. Nem por isso, entretanto, deixa de ser o princípio da vossa matéria pesada." A gravidade é uma propriedade relativa. Fora das esferas de atração dos mundos, não há peso, do mesmo modo que não há alto nem baixo.', 'rascunho'),
  (30, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'A matéria é formada de um só ou de muitos elementos?', 'De um só elemento primitivo. Os corpos que considerais simples não são verdadeiros elementos, são transformações da matéria primitiva.', 'rascunho'),
  (31, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'Donde se originam as diversas propriedades da matéria?', 'São modificações que as moléculas elementares sofrem, por efeito da sua união, em certas circunstâncias.', 'rascunho'),
  (32, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'De acordo com o que vindes de dizer, os sabores, os odores, as cores, o som, as qualidades venenosas ou salutares dos corpos não passam de modificações de uma única substância primitiva?', 'Sem dúvida e que só existem devido à disposição dos órgãos destinados a percebê-las." A demonstração deste princípio se encontra no fato de que nem todos percebemos as qualidades dos corpos do mesmo modo: enquanto que uma coisa agrada ao gosto de um, para o de outro é detestável; o que uns vêem azul, outros vêem vermelho; o que para uns é veneno, para outros é inofensivo ou salutar.', 'rascunho'),
  (33, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'A mesma matéria elementar é suscetível de experimentar todas as modificações e de adquirir todas as propriedades?', 'Sim e é isso o que se deve entender, quando dizemos que tudo está em tudo!" 4 O oxigênio, o hidrogênio, o azoto, o carbono e todos os corpos que consideramos simples são meras modificações de uma substância primitiva. Na impossibilidade em que ainda nos achamos de remontar, a não ser pelo pensamento, a esta matéria primária, esses corpos são para nós verdadeiros elementos e podemos, sem maiores conseqüências, tê-los como tais, até nova ordem. 4 Este princípio explica o fenômeno conhecido de todos os magnetizadores e que consiste em dar-se, pela ação da vontade, a uma substância qualquer, à água, por exemplo, propriedades muito diversas: um gosto determinado e até as qualidades ativas de outras substâncias. Desde que não há mais de um elemento primitivo e que as propriedades dos diferentes corpos são apenas modificações desse elemento, o que se segue é que a mais inofensiva substância tem o mesmo princípio que a mais deletéria. Assim, a água, que se compõe de uma parte de oxigênio e de duas de hidrogênio, se torna corrosiva, duplicando-se a proporção do oxigênio. Transformação análoga se pode produzir por meio da ação magnética dirigida pela vontade. a) — Não parece que esta teoria dá razão aos que não admitem na matéria senão duas propriedades essenciais: a força e o movimento, entendendo que todas as demais propriedades não passam de efeitos secundários, que variam conforme à intensidade da força e à direção do movimento? "É acertada essa opinião. Falta somente acrescentar: e conforme à disposição das moléculas, como o mostra, por exemplo, um corpo opaco, que pode tornar-se transparente e vice-versa.', 'rascunho'),
  (34, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'As moléculas têm forma determinada?', 'Certamente, as moléculas têm uma forma, porém não sois capazes de apreciá-la." a) — Essa forma é constante ou variável? "Constante a das moléculas elementares primitivas; variável a das moléculas secundárias, que mais não são do que aglomerações das primeiras. Porque, o que chamais molécula longe ainda está da molécula elementar.', 'rascunho'),
  (35, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'O Espaço universal é infinito ou limitado?', 'Infinito. Supõe-no limitado: que haverá para lá de seus limites? Isto te confunde a razão, bem o sei; no entanto, a razão te diz que não pode ser de outro modo. O mesmo se dá com o infinito em todas as coisas. Não é na pequenina esfera em que vos achais que podereis compreendê-lo." Supondo-se um limite ao Espaço, por mais distante que a imaginação o coloque, a razão diz que além desse limite alguma coisa há e assim, gradativamente, até ao infinito, porquanto, embora essa alguma coisa fosse o vazio absoluto, ainda seria Espaço.', 'rascunho'),
  (36, 'Parte Primeira — Das causas primárias', 'Capítulo II — Dos elementos gerais do Universo', 'O vácuo absoluto existe em alguma parte no Espaço universal?', 'Não, não há o vácuo. O que te parece vazio está ocupado por matéria que te escapa aos sentidos e aos instrumentos." 50 – Allan Kar dec', 'rascunho'),
  (37, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'O Universo foi criado, ou existe de toda a eternidade, como Deus?', 'É fora de dúvida que ele não pode ter-se feito a si mesmo. Se existisse, como Deus, de toda a eternidade, não seria obra de Deus." Diz-nos a razão não ser possível que o Universo se tenha feito a si mesmo e que, não podendo também ser obra do acaso, há de ser obra de Deus.', 'rascunho'),
  (38, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Como criou Deus o Universo?', 'Para me servir de uma expressão corrente, direi: pela Sua Vontade. Nada caracteriza melhor essa vontade onipotente do que estas belas palavras da Gênese – ‘Deus disse: Faça-se a luz e a luz foi feita.’ ".', 'rascunho'),
  (39, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Poderemos conhecer o modo de formação dos mundos?', 'Tudo o que a esse respeito se pode dizer e podeis compreender é que os mundos se formam pela condensação da matéria disseminada no Espaço.', 'rascunho'),
  (40, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Serão os cometas, como agora se pensa, um começo de condensação da matéria, mundos em via de formação?', 'Isso está certo; absurdo, porém, é acreditar-se na influência deles. Refiro- me à influência que vulgarmente lhes atribuem, porquanto todos os corpos celestes influem de algum modo em certos fenômenos físicos.', 'rascunho'),
  (41, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Pode um mundo completamente formado desaparecer e disseminar-se de novo no Espaço a matéria que o compõe?', 'Sim, Deus renova os mundos, como renova os seres vivos.', 'rascunho'),
  (42, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Poder-se-á conhecer o tempo que dura a formação dos mundos: da Terra, por exemplo?', 'Nada te posso dizer a respeito, porque só o Criador o sabe e bem louco será quem pretenda sabê-lo, ou conhecer que número de séculos dura essa formação.', 'rascunho'),
  (43, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Quando começou a Terra a ser povoada?', 'No começo tudo era caos; os elementos estavam em confusão. Pouco a pouco cada coisa tomou o seu lugar. Apareceram então os seres vivos apropriados ao estado do globo.', 'rascunho'),
  (44, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Donde vieram para a Terra os seres vivos?', 'A Terra lhes continha os germens, que aguardavam momento favorável para se desenvolverem. Os princípios orgânicos se congregaram, desde que cessou a atuação da força que os mantinha afastados, e formaram os germens de todos os seres vivos. Estes germens permaneceram em estado latente de inércia, como a crisálida e as sementes das plantas, até o momento propício ao surto de cada espécie. Os seres de cada uma destas se reuniram, então, e se multiplicaram.', 'rascunho'),
  (45, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Onde estavam os elementos orgânicos, antes da formação da Terra?', 'Achavam-se, por assim dizer, em estado de fluido no Espaço, no meio dos Espíritos, ou em outros planetas, à espera da criação da Terra para começarem existência nova em novo globo." A Química nos mostra as moléculas dos corpos inorgânicos unindo-se para formarem cristais de uma regularidade constante, conforme cada espécie, desde que se encontrem nas condições precisas. A menor perturbação nestas condições basta para impedir a reunião dos elementos, ou, pelo menos, para obstar à disposição regular que constitui o cristal. Por que não se daria o mesmo com os elementos orgânicos? Durante anos se conservam germens de plantas e de animais, que não se desenvolvem senão a uma certa temperatura e em meio apropriado. Têm-se visto grãos de trigo germinarem depois de séculos. Há, pois, nesses germens um princípio latente de vitalidade, que apenas espera uma circunstância favorável para se desenvolver. O que diariamente ocorre debaixo das nossas vistas, por que não pode ter ocorrido desde a origem do globo terráqueo? A formação dos seres vivos, saindo eles do caos pela força mesma da Natureza, diminui de alguma coisa a grandeza de Deus? Longe disso: corresponde melhor à idéia que fazemos do seu poder a se exercer sobre a infinidade dos mundos por meio de leis eternas. Esta teoria não resolve, é verdade, a questão da origem dos elementos vitais; mas, Deus tem seus mistérios e pôs limites às nossas investigações. 52 – Allan Kar dec', 'rascunho'),
  (46, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Ainda há seres que nasçam espontaneamente?', 'Sim, mas o gérmen primitivo já existia em estado latente. Sois todos os dias testemunhas desse fenômeno. Os tecidos do corpo humano e do dos animais não encerram os germens de uma multidão de vermes que só esperam, para desabrochar, a fermentação pútrida que lhes é necessária à existência? É um mundo minúsculo que dormita e se cria.', 'rascunho'),
  (47, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'A espécie humana se encontrava entre os elementos orgânicos contidos no globo terrestre?', 'Sim, e veio a seu tempo. Foi o que deu lugar a que se dissesse que o homem se formou do limo da terra.', 'rascunho'),
  (48, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Poderemos conhecer a época do aparecimento do homem e dos outros seres vivos na Terra?', 'Não; todos os vossos cálculos são quiméricos.', 'rascunho'),
  (49, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Se o gérmen da espécie humana se encontrava entre os elementos orgânicos do globo, por que não se formam espontaneamente homens, como na origem dos tempos?', 'O princípio das coisas está nos segredos de Deus. Entretanto, pode dizer- se que os homens, uma vez espalhados pela Terra, absorveram em si mesmos os elementos necessários à sua própria formação, para os transmitir segundo as leis da reprodução. O mesmo se deu com as diferentes espécies de seres vivos.', 'rascunho'),
  (50, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'A espécie humana começou por um único homem?', 'Não; aquele a quem chamais Adão não foi o primeiro, nem o único a povoar a Terra.', 'rascunho'),
  (51, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Poderemos saber em que época viveu Adão?', 'Mais ou menos na que lhe assinais: cerca de 4.000 anos antes do Cristo." O homem, cuja tradição se conservou sob o nome de Adão, foi dos que sobreviveram, em certa região, a alguns dos grandes cataclismos que revolveram em diversas épocas a superfície do globo, e se constituiu tronco de uma das raças que atualmente o povoam. As leis da Natureza se opõem a que os progressos da Humanidade, comprovados muito tempo antes do Cristo, se tenham realizado em alguns séculos, como houvera sucedido se o homem não existisse na Terra senão a partir da época indicada para a existência de Adão. Muitos, com mais razão, consideram Adão um mito ou uma alegoria que personifica as primeiras idades do mundo.', 'rascunho'),
  (52, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Donde provêm as diferenças físicas e morais que distinguem as raças humanas na Terra?', 'Do clima, da vida e dos costumes. Dá-se aí o que se dá com dois filhos de uma mesma mãe que, educados longe um do outro e de modos diferentes, em nada se assemelharão, quanto ao moral.', 'rascunho'),
  (53, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'O homem surgiu em muitos pontos do globo?', 'Sim e em épocas várias, o que também constitui uma das causas da diversidade das raças. Depois, dispersando-se os homens por climas diversos e aliando-se os de uma aos de outras raças, novos tipos se formaram." a) — Estas diferenças constituem espécies distintas? "Certamente que não; todos são da mesma família. Porventura as múltiplas variedades de um mesmo fruto são motivo para que elas deixem de formar uma só espécie?', 'rascunho'),
  (54, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Pelo fato de não proceder de um só indivíduo a espécie humana, devem os homens deixar de considerar-se irmãos?', 'Todos os homens são irmãos em Deus, porque são animados pelo espírito e tendem para o mesmo fim. Estais sempre inclinados a tomar as palavras na sua significação literal.', 'rascunho'),
  (55, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'São habitados todos os globos que se movem no espaço?', 'Sim e o homem terreno está longe de ser, como supõe, o primeiro em inteligência, em bondade e em perfeição. Entretanto, há homens que se têm por espíritos muito fortes e que imaginam pertencer a este pequenino globo o privilégio de conter seres racionais. Orgulho e vaidade! Julgam que só para eles criou Deus o Universo." Deus povoou de seres vivos os mundos, concorrendo todos esses seres para o objetivo final da Providência. Acreditar que só os haja no planeta que habitamos fora duvidar da sabedoria de Deus, que não fez coisa alguma inútil. Certo, a esses mundos há de ele ter dado uma destinação mais séria do que a de nos recrearem a vista. Aliás, nada há, nem na posição, nem no volume, nem na constituição física da Terra, que possa induzir à suposição de que ela goze do privilégio de ser habitada, com exclusão de tantos milhares de milhões de mundos semelhantes.', 'rascunho'),
  (56, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'É a mesma a constituição física dos diferentes globos?', 'Não; de modo algum se assemelham.', 'rascunho'),
  (57, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Não sendo uma só para todos a constituição física dos mundos, seguir-se-á tenham organizações diferentes os seres que os habitam? 54 – Allan Kar dec', 'Sem dúvida, do mesmo modo que no vosso os peixes são feitos para viver na água e os pássaros no ar.', 'rascunho'),
  (58, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Os mundos mais afastados do Sol estarão privados de luz e calor, por motivo de esse astro se lhes mostrar apenas com a aparência de uma estrela?', 'Pensais então que não há outras fontes de luz e calor além do Sol e em nenhuma conta tendes a eletricidade que, em certos mundos, desempenha um papel que desconheceis e bem mais importante do que o que lhe cabe desempenhar na Terra? Demais, não dissemos que todos os seres são feitos de igual matéria que vós outros e com órgãos de conformação idêntica à dos vossos." As condições de existência dos seres que habitam os diferentes mundos hão de ser adequadas ao meio em que lhes cumpre viver. Se jamais houvéramos visto peixes, não compreenderíamos pudesse haver seres que vivessem dentro d’água. Assim acontece com relação aos outros mundos, que sem dúvida contêm elementos que desconhecemos. Não vemos na Terra as longas noites polares iluminadas pela eletricidade das auroras boreais? Que há de impossível em ser a eletricidade, nalguns mundos, mais abundante do que na Terra e desempenhar neles uma função de ordem geral, cujos efeitos não podemos compreender? Bem pode suceder, portanto, que esses mundos tragam em si mesmos as fontes de calor e de luz necessárias a seus habitantes.', 'rascunho'),
  (59, 'Parte Primeira — Das causas primárias', 'Capítulo III — Da Criação', 'Questão 59', 'Os povos hão formado idéias muito divergentes acerca da Criação, de acordo com as luzes que possuíam. Apoiada na Ciência, a razão reconheceu a inverossimilhança de algumas dessas teorias. A que os Espíritos apresentam confirma a opinião de há muito partilhada pelos homens mais esclarecidos. A objeção que se lhe pode fazer é a de estar em contradição com o texto dos livros sagrados. Mas, um exame sério mostrará que essa contradição é mais aparente do que real e que decorre da interpretação dada ao que muitas vezes só tinha sentido alegórico. A questão de ter sido Adão, como primeiro homem, a origem exclusiva da Humanidade, não é a única a cujo respeito as crenças religiosas tiveram que se modificar. O movimento da Terra pareceu, em determinada época, tão em oposição às letras sagradas, que não houve gênero de perseguições a que essa teoria não tivesse servido de pretexto, e, no entanto, a Terra gira, malgrado aos anátemas, não podendo ninguém hoje contestá-lo, sem agravo à sua própria razão. Diz também a Bíblia que o mundo foi criado em seis dias e põe a época da sua criação há quatro mil anos, mais ou menos, antes da era cristã. Anteriormente, a Terra não existia; foi tirada do nada: o texto é formal. Eis, porém, que a ciência positiva, a inexorável ciência, prova o contrário. A história da formação do globo terráqueo está escrita em caracteres irrecusáveis no mundo fóssil, achando-se provado que os seis dias da criação indicam outros tantos períodos, cada um de, talvez, muitas centenas de milhares de anos. Isto não é um sistema, uma doutrina, uma opinião insulada; é um fato tão certo como o do movimento da Terra e que a Teologia não pode negar-se a admitir, o que demonstra evidentemente o erro em que se está sujeito a cair tomando ao pé da letra expressões de uma linguagem freqüentemente figurada. Dever-se-á daí concluir que a Bíblia é um erro? Não; a conclusão a tirar-se é que os homens se equivocaram ao interpretá-la. Escavando os arquivos da Terra, a Ciência descobriu em que ordem os seres vivos lhe apareceram na superfície, ordem que está de acordo com o que diz a Gênese, havendo apenas a notar-se a diferença de que essa obra, em vez de executada milagrosamente por Deus em algumas horas, se realizou, sempre pela Sua vontade, mas conformemente à lei das forças da Natureza, em alguns milhões de anos. Ficou sendo Deus, por isso, menor e menos poderoso? Perdeu em sublimidade a sua obra, por não ter o prestígio da instantaneidade? Indubitavelmente, não. Fora mister fazer-se da Divindade bem mesquinha idéia, para se não reconhecer a sua onipotência nas leis eternas que ela estabeleceu para regerem os mundos. A Ciência, longe de apoucar a obra divina, no-la mostra sob aspecto mais grandioso e mais acorde com as noções que temos do poder e da majestade de Deus, pela razão mesma de ela se haver efetuado sem derrogação das leis da Natureza. De acordo, neste ponto, com Moisés, a Ciência coloca o homem em último lugar na ordem da criação dos seres vivos. Moisés, porém, indica, como sendo o do dilúvio universal, o ano 4.654 da formação do mundo, ao passo que a Geologia nos aponta o grande cataclismo como anterior ao aparecimento do homem, atendendo a que, até hoje, não se encontrou, nas camadas primitivas, traço algum de sua presença, nem da dos animais de igual categoria, do ponto de vista físico. Contudo, nada prova que isso seja impossível. Muitas descobertas já fizeram surgir dúvidas a tal respeito. Pode dar-se que, de um momento para outro, se adquira a certeza material da anterioridade da raça humana e então se reconhecerá que, a esse propósito, como a tantos outros, o texto bíblico encerra uma figura. A questão está em saber se o cataclismo geológico é o mesmo a que assistiu Noé. Ora, o tempo necessário à formação das camadas fósseis não permite confundi-los e, desde que se achem vestígios da existência do homem antes da grande catástrofe, provado ficará, ou que Adão não foi o primeiro homem, ou que a sua criação se perde na noite dos tempos. Contra a evidência não há raciocínios possíveis; forçoso será aceitar-se esse fato, como se aceitaram o do movimento da Terra e os seis períodos da Criação. A existência do homem antes do dilúvio geológico ainda é, com efeito, hipotética. Eis aqui, porém, alguma coisa que o é menos. Admitindo-se que o homem tenha aparecido pela primeira vez na Terra 4.000 anos antes do Cristo e que, 1.650 anos mais tarde, toda a raça humana foi destruída, com exceção de uma só família, resulta que o povoamento da Terra data apenas de Noé, ou seja: de 2.350 anos antes da nossa era. Ora, quando os hebreus emigraram para o Egito, no décimo oitavo século, encontraram esse país muito povoado e já bastante adiantado em civilização. A História prova que, nessa época, as Índias e outros países também estavam florescentes, sem mesmo se ter em conta a cronologia de certos povos, que remonta a uma época muito mais afastada. Teria sido preciso, nesse caso, que do vigésimo quarto ao décimo oitavo século, isto é, que num espaço de 600 anos, não somente a posteridade de um único homem houvesse podido povoar todos os imensos países então conhecidos, suposto que os outros não o fossem, mas também que, nesse curto lapso de tempo, a espécie humana houvesse podido elevar-se da ignorância absoluta do estado primitivo ao mais alto grau de desenvolvimento intelectual, o que é contrário a todas as leis antropológicas. A diversidade das raças corrobora, igualmente, esta opinião. O clima e os costumes produzem, é certo, modificações no caráter físico; sabe-se, porém, até onde pode ir a influência dessas causas. Entretanto, o exame fisiológico demonstra haver, entre certas raças, diferenças constitucionais mais profundas do que as que o clima é capaz de determinar. O cruzamento das raças dá origem aos tipos intermediários. Ele tende a apagar os caracteres extremos, mas não os cria; apenas produz variedades. Ora, para que tenha havido cruzamento de raças, preciso era que houvesse raças distintas. Como, porém, se explicará a existência delas, atribuindo-se-lhes uma origem comum e, sobretudo, tão pouco afastada? Como se há de admitir que, em poucos séculos, alguns descendentes de Noé se tenham transformado ao ponto de produzirem a raça etíope, por exemplo? Tão pouco 56 – Allan Kar dec admissível é semelhante metamorfose, quanto a hipótese de uma origem comum para o lobo e o cordeiro, para o elefante e o pulgão, para o pássaro e o peixe. Ainda uma vez: nada pode prevalecer contra a evidência dos fatos. Tudo, ao invés, se explica, admitindo-se: que a existência do homem é anterior à época em que vulgarmente se pretende que ela começou; que diversas são as origens; que Adão, vivendo há seis mil anos, tenha povoado uma região ainda desabitada; que o dilúvio de Noé foi uma catástrofe parcial, confundida com o cataclismo geológico; e atentando-se, finalmente, na forma alegórica peculiar ao estilo oriental, forma que se nos depara nos livros sagrados de todos os povos. Isto faz ver quanto é prudente não lançar levianamente a pecha de falsas as doutrinas que podem, cedo ou tarde, como tantas outras, desmentir os que as combatem. As idéias religiosas, longe de perderem alguma coisa, se engrandecem, caminhando de par com a Ciência. Esse o meio único de não apresentarem lado vulnerável ao cepticismo.', 'rascunho'),
  (60, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'É a mesma a força que une os elementos da matéria nos corpos orgânicos e nos inorgânicos?', 'Sim, a lei de atração é a mesma para todos.', 'rascunho'),
  (61, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'Há diferença entre a matéria dos corpos orgânicos e a dos inorgânicos?', 'A matéria é sempre a mesma, porém nos corpos orgânicos está animalizada.', 'rascunho'),
  (62, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'Qual a causa da animalização da matéria?', 'Sua união com o princípio vital.', 'rascunho'),
  (63, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'O princípio vital reside nalgum agente particular, ou é simplesmente uma propriedade da matéria organizada? Numa palavra, é efeito, ou causa?', 'Uma e outra coisa. A vida é um efeito devido à ação de um agente sobre a matéria. Esse agente, sem a matéria, não é a vida, do mesmo modo que a matéria não pode viver sem esse agente. Ele dá a vida a todos os seres que o absorvem e assimilam.', 'rascunho'),
  (64, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'Vimos que o espírito e a matéria são dois elementos constitutivos do Universo. O princípio vital será um terceiro?', 'É, sem dúvida, um dos elementos necessários à constituição do Universo, mas que também tem sua origem na matéria universal modificada. É, para vós, um elemento, 58 – Allan Kar dec como o oxigênio e o hidrogênio, que, entretanto, não são elementos primitivos, pois que tudo isso deriva de um só princípio." a) — Parece resultar daí que a vitalidade não tem seu princípio num agente primitivo distinto e sim numa propriedade especial da matéria universal, devida a certas modificações. "Isto é conseqüência do que dissemos.', 'rascunho'),
  (65, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'O princípio vital reside em algum dos corpos que conhecemos?', 'Ele tem por fonte o fluido universal. É o que chamais fluido magnético, ou fluido elétrico animalizado. É o intermediário, o elo existente entre o Espírito e a matéria.', 'rascunho'),
  (66, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'O princípio vital é um só para todos os seres orgânicos?', 'Sim, modificado segundo as espécies. É ele que lhes dá movimento e atividade e os distingue da matéria inerte, porquanto o movimento da matéria não é a vida. Esse movimento ela o recebe, não o dá.', 'rascunho'),
  (67, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'A vitalidade é atributo permanente do agente vital, ou se desenvolve tão-só pelo funcionamento dos órgãos?', 'Ela não se desenvolve senão com o corpo. Não dissemos que esse agente sem a matéria não é a vida? A união dos dois é necessária para produzir a vida." a) — Poder-se-á dizer que a vitalidade se acha em estado latente, quando o agente vital não está unido ao corpo? "Sim, é isso." O conjunto dos órgãos constitui uma espécie de mecanismo que recebe impulsão da atividade íntima ou princípio vital que entre eles existe. O princípio vital é a força motriz dos corpos orgânicos. Ao mesmo tempo em que o agente vital dá impulsão aos órgãos, a ação destes entretém e desenvolve a atividade daquele agente, quase como sucede com o atrito, que desenvolve o calor.', 'rascunho'),
  (68, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'Qual a causa da morte dos seres orgânicos?', 'Esgotamento dos órgãos." a) — Poder-se-ia comparar a morte à cessação do movimento de uma máquina desorganizada? "Sim; se a máquina está mal montada, cessa o movimento; se o corpo está enfermo, a vida se extingue.', 'rascunho'),
  (69, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'Por que é que uma lesão do coração mais depressa causa a morte do que as de outros órgãos?', 'O coração é máquina de vida, não é, porém, o único órgão cuja lesão ocasiona a morte. Ele não passa de uma das peças essenciais.', 'rascunho'),
  (70, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'Que é feito da matéria e do princípio vital dos seres orgânicos, quando estes morrem?', 'A matéria inerte se decompõe e vai formar novos organismos. O princípio vital volta à massa donde saiu." Morto o ser orgânico, os elementos que o compõem sofrem novas combinações, de que resultam novos seres, os quais haurem na fonte universal o princípio da vida e da atividade, o absorvem e assimilam, para novamente o restituírem a essa fonte, quando deixarem de existir. Os órgãos se impregnam, por assim dizer, desse fluido vital e esse fluido dá a todas as partes do organismo uma atividade que as põe em comunicação entre si, nos casos de certas lesões, e normaliza as funções momentaneamente perturbadas. Mas, quando os elementos essenciais ao funcionamento dos órgãos estão destruídos, ou muito profundamente alterados, o fluido vital se torna impotente para lhes transmitir o movimento da vida, e o ser morre. Mais ou menos necessariamente, os órgãos reagem uns sobre os outros, resultando essa ação recíproca da harmonia do conjunto por eles formado. Destruída que seja, por uma causa qualquer, esta harmonia, o funcionamento deles cessa, como o movimento da máquina cujas peças principais se desarranjem. É o que se verifica, por exemplo, com um relógio gasto pelo uso, ou que sofreu um choque por acidente, no qual a força motriz fica impotente para pô-lo de novo a andar. Num aparelho elétrico temos imagem mais exata da vida e da morte. Esse aparelho, como todos os corpos da Natureza, contém eletricidade em estado latente. Os fenômenos elétricos, porém, não se produzem senão quando o fluido é posto em atividade por uma causa especial. Poder-se-ia então dizer que o aparelho está vivo. Vindo a cessar a causa da atividade, cessa o fenômeno: o aparelho volta ao estado de inércia. Os corpos orgânicos são, assim, uma espécie de pilhas ou aparelhos elétricos, nos quais a atividade do fluido determina o fenômeno da vida. A cessação dessa atividade causa a morte. A quantidade de fluido vital não é absoluta em todos os seres orgânicos. Varia segundo as espécies e não é constante, quer em cada indivíduo, quer nos indivíduos de uma espécie. Alguns há, que se acham, por assim dizer, saturados desse fluido, enquanto outros o possuem em quantidade apenas suficiente. Daí, para alguns, vida mais ativa, mais tenaz e, de certo modo, superabundante. A quantidade de fluido vital se esgota. Pode tornar-se insuficiente para a conservação da vida, se não for renovada pela absorção e assimilação das substâncias que o contêm. O fluido vital se transmite de um indivíduo a outro. Aquele que o tiver em maior porção pode dá-lo a um que o tenha de menos e em certos casos prolongar a vida prestes a extinguir-se.', 'rascunho'),
  (71, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'A inteligência é atributo do princípio vital?', 'Não, pois que as plantas vivem e não pensam: só têm vida orgânica. A inteligência e a matéria são independentes, porquanto um corpo pode viver sem a inteligência. Mas, a inteligência só por meio dos órgãos materiais pode manifestar- se. Necessário é que o espírito se una à matéria animalizada para intelectualizá-la." A inteligência é uma faculdade especial, peculiar a algumas classes de seres orgânicos e que lhes dá, com o pensamento, a vontade de atuar, a consciência de que existem 60 – Allan Kar dec e de que constituem uma individualidade cada um, assim como os meios de estabelecerem relações com o mundo exterior e de proverem às suas necessidades. Podem distinguir-se assim: lº, os seres inanimados, constituídos só de matéria, sem vitalidade nem inteligência: são os corpos brutos; 2º, os seres animados que não pensam, formados de matéria e dotados de vitalidade, porém, destituídos de inteligência; 3º, os seres animados pensantes, formados de matéria, dotados de vitalidade e tendo a mais um princípio inteligente que lhes outorga a faculdade de pensar.', 'rascunho'),
  (72, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'Qual a fonte da inteligência?', 'Já o dissemos; a inteligência universal." a) — Poder-se-ia dizer que cada ser tira uma porção de inteligência da fonte universal e a assimila, como tira e assimila o princípio da vida material? "Isto não passa de simples comparação, todavia inexata, porque a inteligência é uma faculdade própria de cada ser e constitui a sua individualidade moral. Demais, como sabeis, há coisas que ao homem não é dado penetrar e esta, por enquanto, é desse número.', 'rascunho'),
  (73, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'O instinto independe da inteligência?', 'Precisamente, não, por isso que o instinto é uma espécie de inteligência. É uma inteligência sem raciocínio. Por ele é que todos os seres provêem às suas necessidades.', 'rascunho'),
  (74, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'Pode estabelecer-se uma linha de separação entre instinto e a inteligência, isto é, precisar onde um acaba e começa a outra?', 'Não, porque muitas vezes se confundem. Mas, muito bem se podem distinguir os atos que decorrem do instinto dos que são da inteligência.', 'rascunho'),
  (75, 'Parte Primeira — Das causas primárias', 'Capítulo IV — Do princípio vital', 'É acertado dizer-se que as faculdades instintivas diminuem à medida que crescem as intelectuais?', 'Não; o instinto existe sempre, mas o homem o despreza. O instinto também pode conduzir ao bem. Ele quase sempre nos guia e algumas vezes com mais segurança do que a razão. Nunca se transvia." a) — Por que nem sempre é guia infalível a razão? "Seria infalível, se não fosse falseada pela má-educação, pelo orgulho e pelo egoísmo. O instinto não raciocina; a razão permite a escolha e dá ao homem o livre-arbítrio." O instinto é uma inteligência rudimentar, que difere da inteligência propriamente dita, em que suas manifestações são quase sempre espontâneas, ao passo que as da inteligência resultam de uma combinação e de um ato deliberado. O instinto varia em suas manifestações, conforme às espécies e às suas necessidades. Nos seres que têm a consciência e a percepção das coisas exteriores, ele se alia à inteligência, isto é, à vontade e à liberdade.', 'rascunho'),
  (76, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Que definição se pode dar dos Espíritos?', 'Pode dizer-se que os Espíritos são os seres inteligentes da criação. Povoam o Universo, fora do mundo material." Nota — A palavra Espírito é empregada aqui para designar as individualidades dos seres extracorpóreos e não mais o elemento inteligente do Universo.', 'rascunho'),
  (77, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os Espíritos são seres distintos da Divindade, ou serão simples emanações ou porções desta e, por isto, denominados filhos de Deus?', 'Meu Deus! São obra de Deus, exatamente qual a máquina o é do homem que a fabrica. A máquina é obra do homem, não é o próprio homem. Sabes que, quando faz alguma coisa bela, útil, o homem lhe chama sua filha, criação sua. Pois bem! O mesmo se dá com relação a Deus: somos seus filhos, pois que somos obra sua.', 'rascunho'),
  (78, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os Espíritos tiveram princípio, ou existem, como Deus, de toda a eternidade?', 'Se não tivessem tido princípio, seriam iguais a Deus, quando, ao invés, são criação sua e se acham submetidos à sua vontade. Deus existe de toda a eternidade, é incontestável. Quanto, porém, ao modo por que nos criou e em que momento o fez, nada sabemos. Podes dizer que não tivemos princípio, se quiseres com isso significar que, sendo eterno, Deus há de ter sempre criado ininterruptamente. Mas, quando e como cada um de nós foi feito, repito-te, nenhum o sabe: aí é que está o mistério.', 'rascunho'),
  (79, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Pois que há dois elementos gerais no Universo: o elemento inteligente e o elemento material, poder-se-á dizer que os Espíritos são formados do elemento inteligente, como os corpos inertes o são do elemento material?', 'Evidentemente. Os Espíritos são a individualização do princípio inteligente, como os corpos são a individualização do princípio material. A época e o modo por que essa formação se operou é que são desconhecidos.', 'rascunho'),
  (80, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'A criação dos Espíritos é permanente, ou só se deu na origem dos tempos?', 'É permanente. Quer dizer: Deus jamais deixou de criar.', 'rascunho'),
  (81, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os Espíritos se formam espontaneamente, ou procedem uns dos outros?', 'Deus os cria, como a todas as outras criaturas, pela sua vontade. Mas, repito ainda uma vez, a origem deles é mistério.', 'rascunho'),
  (82, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Será certo dizer-se que os Espíritos são imateriais?', 'Como se pode definir uma coisa, quando faltam termos de comparação e com uma linguagem deficiente? Pode um cego de nascença definir a luz? Imaterial não é bem o termo; incorpóreo seria mais exato, pois deves compreender que, sendo uma criação, o Espírito há de ser alguma coisa. É a matéria quintessenciada, mas sem analogia para vós outros, e tão etérea que escapa inteiramente ao alcance dos vossos sentidos." Dizemos que os Espíritos são imateriais, porque, pela sua essência, diferem de tudo o que conhecemos sob o nome de matéria. Um povo de cegos careceria de termos para exprimir a luz e seus efeitos. O cego de nascença se julga capaz de todas as percepções pelo ouvido, pelo olfato, pelo paladar e pelo tato. Não compreende as idéias que só lhe poderiam ser dadas pelo sentido que lhe falta. Nós outros somos verdadeiros cegos com relação à essência dos seres sobre-humanos. Não os podemos definir senão por meio de comparações sempre imperfeitas, ou por um esforço da imaginação.', 'rascunho'),
  (83, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os Espíritos têm fim? Compreende-se que seja eterno o princípio donde eles emanam, mas o que perguntamos é se suas individualidades têm um termo e se, em dado tempo, mais ou menos longo, o elemento de que são formados não se dissemina e volta à massa donde saiu como sucede com os corpos materiais. É difícil de conceber-se que uma coisa que teve começo possa não ter fim.', 'Há muitas coisas que não compreendeis, porque tendes limitada a inteligência. Isso, porém, não é razão para que as repilais. O filho não compreende tudo o que a seu pai é compreensível, nem o ignorante tudo o que o sábio apreende. Dizemos que a existência dos Espíritos não tem fim. É tudo o que podemos, por agora, dizer." 64 – Allan Kar dec', 'rascunho'),
  (84, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os Espíritos constituem um mundo à parte, fora daquele que vemos?', 'Sim, o mundo dos Espíritos, ou das inteligências incorpóreas.', 'rascunho'),
  (85, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Qual dos dois, o mundo espírita ou o mundo corpóreo, é o principal, na ordem das coisas?', 'O mundo espírita, que preexiste e sobrevive a tudo.', 'rascunho'),
  (86, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'O mundo corporal poderia deixar de existir, ou nunca ter existido, sem que isso alterasse a essência do mundo espírita?', 'Decerto. Eles são independentes; contudo, é incessante a correlação entre ambos, porquanto um sobre o outro incessantemente reagem.', 'rascunho'),
  (87, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Ocupam os Espíritos uma região determinada e circunscrita no espaço?', 'Estão por toda parte. Povoam infinitamente os espaços infinitos. Tendes muitos deles de contínuo a vosso lado, observando-vos e sobre vós atuando, sem o perceberdes, pois que os Espíritos são uma das potências da natureza e os instrumentos de que Deus se serve para execução de seus desígnios providenciais. Nem todos, porém, vão a toda parte, por isso que há regiões interditas aos menos adiantados.', 'rascunho'),
  (88, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os Espíritos têm forma determinada, limitada e constante?', 'Para vós, não; para nós, sim. O Espírito é, se quiserdes, uma chama, um clarão, ou uma centelha etérea." a) — Essa chama ou centelha tem cor? "Tem uma coloração que, para vós, vai do colorido escuro e opaco a uma cor brilhante, qual a do rubi, conforme o Espírito é mais ou menos puro." Representam-se de ordinário os gênios com uma chama ou estrela na fronte. É uma alegoria, que lembra a natureza essencial dos Espíritos. Colocam-na no alto da cabeça, porque aí está a sede da inteligência.', 'rascunho'),
  (89, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os Espíritos gastam algum tempo para percorrer o espaço?', 'Sim, mas fazem-no com a rapidez do pensamento." a) — O pensamento não é a própria alma que se transporta? "Quando o pensamento está em alguma parte, a alma também aí está, pois que é a alma quem pensa. O pensamento é um atributo.', 'rascunho'),
  (90, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'O Espírito que se transporta de um lugar a outro tem consciência da distância que percorre e dos espaços que atravessa, ou é subitamente transportado ao lugar onde quer ir?', 'Dá-se uma e outra coisa. O Espírito pode perfeitamente, se o quiser, inteirar-se da distância que percorre, mas também essa distância pode desaparecer completamente, dependendo isso da sua vontade, bem como da sua natureza mais ou menos depurada.', 'rascunho'),
  (91, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'A matéria opõe obstáculo aos Espíritos?', 'Nenhum; eles passam através de tudo. O ar, a terra, as águas e até mesmo o fogo lhes são igualmente acessíveis.', 'rascunho'),
  (92, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Têm os Espíritos o dom da ubiqüidade? Por outras palavras: um Espírito pode dividir-se, ou existir em muitos pontos ao mesmo tempo?', 'Não pode haver divisão de um mesmo Espírito; mas, cada um é um centro que irradia para diversos lados. Isso é que faz parecer estar um Espírito em muitos lugares ao mesmo tempo. Vês o Sol? É um somente. No entanto, irradia em todos os sentidos e leva muito longe os seus raios. Contudo, não se divide." a) — Todos os Espíritos irradiam com igual força? "Longe disso. Essa força depende do grau de pureza de cada um." Cada Espírito é uma unidade indivisível, mas cada um pode lançar seus pensamentos para diversos lados, sem que se fracione para tal efeito. Nesse sentido unicamente é que se deve entender o dom da ubiqüidade atribuído aos Espíritos. Dá-se com eles o que se dá com uma centelha, que projeta longe a sua claridade e pode ser percebida de todos os pontos do horizonte; ou, ainda, o que se dá com um homem que, sem mudar de lugar e sem se fracionar, transmite ordens, sinais e movimento a diferentes pontos. P E R I SP Í R I T O', 'rascunho'),
  (93, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'O Espírito, propriamente dito, nenhuma cobertura tem, ou, como pretendem alguns, está sempre envolto numa substância qualquer?', 'Envolve-o uma substância, vaporosa para os teus olhos, mas ainda bastante grosseira para nós; assaz vaporosa, entretanto, para poder elevar-se na atmosfera e transportar-se aonde queira." Envolvendo o gérmen de um fruto, há o perisperma; do mesmo modo, uma substância que, por comparação, se pode chamar perispírito, serve de envoltório ao Espírito propriamente dito.', 'rascunho'),
  (94, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'De onde tira o Espírito o seu invólucro semimaterial?', 'Do fluido universal de cada globo, razão por que não é idêntico em todos os mundos. Passando de um mundo a outro, o Espírito muda de envoltório, como mudais de roupa." a) — Assim, quando os Espíritos que habitam mundos superiores vêm ao nosso meio, tomam um perispírito mais grosseiro? "É necessário que se revistam da vossa matéria, já o dissemos.', 'rascunho'),
  (95, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'O invólucro semimaterial do Espírito tem formas determinadas e pode ser perceptível? 66 – Allan Kar dec', 'Tem a forma que o Espírito queira. É assim que este vos aparece algumas vezes, quer em sonho, quer no estado de vigília, e que pode tomar forma visível, mesmo palpável.', 'rascunho'),
  (96, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'São iguais os Espíritos, ou há entre eles qualquer hierarquia?', 'São de diferentes ordens, conforme o grau de perfeição que tenham alcançado.', 'rascunho'),
  (97, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'As ordens ou graus de perfeição dos Espíritos são em número determinado?', 'São ilimitadas em número, porque entre elas não há linhas de demarcação traçadas como barreiras, de sorte que as divisões podem ser multiplicadas ou restringidas livremente. Todavia, considerando-se os caracteres gerais dos Espíritos, elas podem reduzir-se a três principais." "Na primeira, colocar-se-ão os que atingiram a perfeição máxima: os puros Espíritos. Formam a segunda os que chegaram ao meio da escala: o desejo do bem é o que neles predomina. Pertencerão à terceira os que ainda se acham na parte inferior da escala: os Espíritos imperfeitos. A ignorância, o desejo do mal e todas as paixões más que lhes retardam o progresso, eis o que os caracteriza.', 'rascunho'),
  (98, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os Espíritos da segunda ordem, para os quais o bem constitui a preocupação dominante, têm o poder de praticá-lo?', 'Cada um deles dispõe desse poder, de acordo com o grau de perfeição a que chegou. Assim, uns possuem a ciência, outros a sabedoria e a bondade. Todos, porém, ainda têm que sofrer provas.', 'rascunho'),
  (99, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os da terceira categoria são todos essencialmente maus?', 'Não; uns há que não fazem nem o mal nem o bem; outros, ao contrário, se comprazem no mal e ficam satisfeitos quando se lhes depara ocasião de praticá-lo. Há também os levianos ou estouvados, mais perturbadores do que malignos, que se comprazem antes na malícia do que na malvadez e cujo prazer consiste em mistificar e causar pequenas contrariedades, de que se riem.', 'rascunho'),
  (100, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Observações preliminares.', 'A classificação dos Espíritos se baseia no grau de adiantamento deles, nas qualidades que já adquiriram e nas imperfeições de que ainda terão de despojar-se. Esta classificação, aliás, nada tem de absoluta. Apenas no seu conjunto cada categoria apresenta caráter definido. De um grau a outro a transição é insensível e, nos limites extremos, os matizes se apagam, como nos reinos da natureza, como nas cores do arco-íris, ou, também, como nos diferentes períodos da vida do homem. Podem, pois, formar-se maior ou menor número de classes, conforme o ponto de vista donde se considere a questão. Dá-se aqui o que se dá com todos os sistemas de classificação científica, que podem ser mais ou menos completos, mais ou menos racionais, mais ou menos cômodos para a inteligência. Sejam, porém, quais forem, em nada alteram as bases da ciência. Assim, é natural que inquiridos sobre este ponto, hajam os Espíritos divergido quanto ao número das categorias, sem que isto tenha valor algum. Entretanto, não faltou quem se agarrasse a esta contradição aparente, sem refletir que os Espíritos nenhuma importância ligam ao que é puramente convencional. Para eles, o pensamento é tudo. Deixam-nos a nós a forma, a escolha dos termos, as classificações, numa palavra, os sistemas. Façamos ainda uma consideração que se não deve jamais perder de vista, a de que entre os Espíritos, do mesmo modo que entre os homens, há os muito ignorantes, de maneira que nunca serão demais as cautelas que se tomem contra a tendência a crer que, por serem Espíritos, todos devam saber tudo. Qualquer classificação exige método, análise e conhecimento aprofundado do assunto. Ora, no mundo dos Espíritos, os que possuem limitados conhecimentos são, como neste mundo, os ignorantes, os inaptos a apreender uma síntese, a formular um sistema. Só muito imperfeitamente percebem ou compreendem uma classificação qualquer. Consideram da primeira categoria todos os Espíritos que lhes são superiores, por não poderem apreciar as gradações de saber, de capacidade e de moralidade que os distinguem, como sucede entre nós a um homem rude com relação aos civilizados. Mesmo os que sejam capazes de tal apreciação podem mostrar-se divergentes, quanto às particularidades, conformemente aos pontos de vista em que se achem, sobretudo se se trata de uma divisão, que nenhum cunho absoluto apresente. Lineu, Jussieu e Tournefort tiveram cada um o seu método, sem que a Botânica houvesse em conseqüência experimentado modificação alguma. É que nenhum deles inventou as plantas, nem seus caracteres. Apenas observaram as analogias, segundo as quais formaram os grupos ou classes. Foi assim que também nós procedemos. Não inventamos os Espíritos, nem seus caracteres. Vimos e observamos, julgamo-los pelas suas palavras e atos, depois os classificamos pelas semelhanças, baseando-nos em dados que eles próprios nos forneceram. Os Espíritos, em geral, admitem três categorias principais, ou três grandes divisões. Na última, a que fica na parte inferior da escala, estão os Espíritos imperfeitos, caracterizados pela predominância da matéria sobre o espírito e pela propensão para o mal. Os da segunda se caracterizam pela predominância do espírito sobre a matéria e pelo desejo do bem: são os bons Espíritos. A primeira, finalmente, compreende os Espíritos puros, os que atingiram o grau supremo da perfeição. Esta divisão nos pareceu perfeitamente racional e com caracteres bem positivados. Só nos restava pôr em relevo, mediante subdivisões em número suficiente, os principais matizes do conjunto. Foi o que fizemos, com o concurso dos Espíritos, cujas benévolas instruções jamais nos faltaram. Com o auxílio desse quadro, fácil será determinar-se a ordem, assim como o grau de superioridade ou de inferioridade dos que possam entrar em relações conosco e, por conseguinte, o grau de confiança ou de estima que mereçam. É, de certo modo, a chave da ciência espírita, porquanto só ele pode explicar as anomalias que as comunicações apresentam, esclarecendo-nos acerca das 68 – Allan Kar dec desigualdades intelectuais e morais dos Espíritos. Faremos, todavia, notar que estes não ficam pertencendo, exclusivamente, a tal ou tal classe. Sendo sempre gradual o progresso deles e muitas vezes mais acentuado num sentido do que em outro, pode acontecer que muitos reúnam em si os caracteres de várias categorias, o que seus atos e linguagem tornam possível apreciar-se.', 'rascunho'),
  (101, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Caracteres gerais.', 'Predominância da matéria sobre o espírito. Propensão para o mal. Ignorância, orgulho, egoísmo e todas as paixões que lhes são conseqüentes. Têm a intuição de Deus, mas não o compreendem. Nem todos são essencialmente maus. Em alguns há mais leviandade, irreflexão e malícia do que verdadeira maldade. Uns não fazem o bem nem o mal; mas, pelo simples fato de não fazerem o bem, já denotam a sua inferioridade. Outros, ao contrário, se comprazem no mal e rejubilam quando uma ocasião se lhes depara de praticá-lo. A inteligência pode achar-se neles aliada à maldade ou à malícia; seja, porém, qual for o grau que tenham alcançado de desenvolvimento intelectual, suas idéias são pouco elevadas e mais ou menos abjetos seus sentimentos. Restritos conhecimentos têm das coisas do mundo espírita e o pouco que sabem se confunde com as idéias e preconceitos da vida corporal. Não nos podem dar mais do que noções errôneas e incompletas; entretanto, nas suas comunicações, mesmo imperfeitas, o observador atento encontra a confirmação das grandes verdades ensinadas pelos Espíritos superiores. Na linguagem de que usam se lhes revela o caráter. Todo Espírito que, em suas comunicações, trai um mau pensamento, pode ser classificado na terceira ordem. Conseguintemente, todo mau pensamento que nos é sugerido vem de um Espírito desta ordem. Eles vêem a felicidade dos bons e esse espetáculo lhes constitui incessante tormento, porque os faz experimentar todas as angústias que a inveja e o ciúme podem causar. Conservam a lembrança e a percepção dos sofrimentos da vida corpórea e essa impressão é muitas vezes mais penosa do que a realidade. Sofrem, pois, verdadeiramente, pelos males de que padeceram em vida e pelos que ocasionam aos outros. E, como sofrem por longo tempo, julgam que sofrerão para sempre. Deus, para puni-los, quer que assim julguem. Podem compor cinco classes principais.', 'rascunho'),
  (102, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Décima classe. Espíritos impuros.', 'São inclinados ao mal, de que fazem o objeto de suas preocupações. Como Espíritos, dão conselhos pérfidos, sopram a discórdia e a desconfiança e se mascaram de todas as maneiras para melhor enganar. Ligam-se aos homens de caráter bastante fraco para cederem às suas sugestões, a fim de induzi-los à perdição, satisfeitos com o conseguirem retardar- lhes o adiantamento, fazendo-os sucumbir nas provas por que passam. Nas manifestações dão-se a conhecer pela linguagem. A trivialidade e a grosseria das expressões, nos Espíritos, como nos homens, é sempre indício de inferioridade moral, senão também intelectual. Suas comunicações exprimem a baixeza de seus pendores e, se tentam iludir, falando com sensatez, não conseguem sustentar por muito tempo o papel e acabam sempre por se traírem. Alguns povos os arvoraram em divindades maléficas; outros os designam pelos nomes de demônios, maus gênios, Espíritos do mal. Quando encarnados, os seres vivos que eles constituem se mostram propensos a todos os vícios geradores das paixões vis e degradantes: a sensualidade, a crueldade, a felonia, a hipocrisia, a cupidez, a avareza sórdida. Fazem o mal por prazer, as mais das vezes sem motivo, e, por ódio ao bem, quase sempre escolhem suas vítimas entre as pessoas honestas. São flagelos para a Humanidade, pouco importando a categoria social a que pertençam, e o verniz da civilização não os forra ao opróbrio e à ignomínia.', 'rascunho'),
  (103, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Nona classe. Espíritos levianos.', 'São ignorantes, maliciosos, irrefletidos e zombeteiros. Metem-se em tudo, a tudo respondem, sem se incomodarem com a verdade. Gostam de causar pequenos desgostos e ligeiras alegrias, de intrigar, de induzir maldosamente em erro, por meio de mistificações e de espertezas. A esta classe pertencem os Espíritos vulgarmente tratados de duendes, trasgos, gnomos, diabretes. Acham-se sob a dependência dos Espíritos superiores, que muitas vezes os empregam, como fazemos com os nossos servidores. Em suas comunicações com os homens, a linguagem de que se servem é, amiúde, espirituosa e faceta, mas quase sempre sem profundeza de idéias. Aproveitam-se das esquisitices e dos ridículos humanos e os apreciam, mordazes e satíricos. Se tomam nomes supostos, é mais por malícia do que por maldade.', 'rascunho'),
  (104, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Oitava classe. Espíritos pseudo', 'SÁBIOS. — Dispõem de conhecimentos bastante amplos, porém, crêem saber mais do que realmente sabem. Tendo realizado alguns progressos sob diversos pontos de vista, a linguagem deles aparenta um cunho de seriedade, de natureza a iludir com respeito às suas capacidades e luzes. Mas, em geral, isso não passa de reflexo dos preconceitos e idéias sistemáticas que nutriam na vida terrena. É uma mistura de algumas verdades com os erros mais polpudos, através dos quais penetram a presunção, o orgulho, o ciúme e a obstinação, de que ainda não puderam despir-se.', 'rascunho'),
  (105, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Sétima classe. Espíritos neutros.', 'Nem bastante bons para fazerem o bem, nem bastante maus para fazerem o mal. Pendem tanto para um como para o outro e não ultrapassam a condição comum da Humanidade, quer no que concerne ao moral, quer no que toca à inteligência. Apegam-se às coisas deste mundo, de cujas grosseiras alegrias sentem saudades.', 'rascunho'),
  (106, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Sexta classe. Espíritos batedores e perturbadores.', 'Estes Espíritos, propriamente falando, não formam uma classe distinta pelas suas qualidades pessoais. Podem caber em todas as classes da terceira ordem. Manifestam geralmente sua presença por efeitos sensíveis e físicos, como pancadas, movimento 70 – Allan Kar dec e deslocamento anormal de corpos sólidos, agitação do ar, etc. Afiguram-se, mais do que outros, presos à matéria. Parecem ser os agentes principais das vicissitudes dos elementos do globo, quer atuem sobre o ar, a água, o fogo, os corpos duros, quer nas entranhas da terra. Reconhece-se que esses fenômenos não derivam de uma causa fortuita ou física, quando denotam caráter intencional e inteligente. Todos os Espíritos podem produzir tais fenômenos, mas os de ordem elevada os deixam, de ordinário, como atribuições dos subalternos, mais aptos para as coisas materiais do que para as coisas da inteligência; quando julgam úteis as manifestações desse gênero, lançam mão destes últimos como seus auxiliares.', 'rascunho'),
  (107, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Caracteres gerais.', 'Predominância do Espírito sobre a matéria; desejo do bem. Suas qualidades e poderes para o bem estão em relação com o grau de adiantamento que hajam alcançado; uns têm a ciência, outros a sabedoria e a bondade. Os mais adiantados reúnem o saber às qualidades morais. Não estando ainda completamente desmaterializados, conservam mais ou menos, conforme a categoria que ocupem, os traços da existência corporal, assim na forma da linguagem, como nos hábitos, entre os quais se descobrem mesmo algumas de suas manias. De outro modo, seriam Espíritos perfeitos. Compreendem Deus e o infinito e já gozam da felicidade dos bons. São felizes pelo bem que fazem e pelo mal que impedem. O amor que os une lhes é fonte de inefável ventura, que não tem a perturbá-la nem a inveja, nem os remorsos, nem nenhuma das más paixões que constituem o tormento dos Espíritos imperfeitos. Todos, entretanto, ainda têm que passar por provas, até que atinjam a perfeição. Como Espíritos, suscitam bons pensamentos, desviam os homens da senda do mal, protegem na vida os que se lhes mostram dignos de proteção e neutralizam a influência dos Espíritos imperfeitos sobre aqueles a quem não é grato sofrê-la. Quando encarnados, são bondosos e benevolentes com os seus semelhantes. Não os movem o orgulho, nem o egoísmo, ou a ambição. Não experimentam ódio, rancor, inveja ou ciúme e fazem o bem pelo bem. A esta ordem pertencem os Espíritos designados, nas crenças vulgares, pelos nomes de bons gênios, gênios protetores, Espíritos do bem. Em épocas de superstições e de ignorância, eles hão sido elevados à categoria de divindades benfazejas. Podem ser divididos em quatro grupos principais:', 'rascunho'),
  (108, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Quinta classe. Espíritos benévolos.', 'A bondade é neles a qualidade dominante. Apraz-lhes prestar serviço aos homens e protegê-los. Limitados, porém, são os seus conhecimentos. Hão progredido mais no sentido moral do que no sentido intelectual.', 'rascunho'),
  (109, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Quarta classe. Espíritos sábios.', 'Distinguem-se pela amplitude de seus conhecimentos. Preocupam-se menos com as questões morais, do que com as de natureza científica, para as quais têm maior aptidão. Entretanto, só encaram a ciência do ponto de vista da sua utilidade e jamais dominados por quaisquer paixões próprias dos Espíritos imperfeitos.', 'rascunho'),
  (110, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Terceira classe. Espíritos de sabedoria.', 'As qualidades morais da ordem mais elevada são o que os caracteriza. Sem possuírem ilimitados conhecimentos, são dotados de uma capacidade intelectual que lhes faculta juízo reto sobre os homens e as coisas.', 'rascunho'),
  (111, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Segunda classe. Espíritos superiores.', 'Esses em si reúnem a ciência, a sabedoria e a bondade. Da linguagem que empregam se exala sempre a benevolência; é uma linguagem invariavelmente digna, elevada e, muitas vezes, sublime. Sua superioridade os torna mais aptos do que os outros a nos darem noções exatas sobre as coisas do mundo incorpóreo, dentro dos limites do que é permitido ao homem saber. Comunicam-se complacentemente com os que procuram de boa-fé a verdade e cuja alma já está bastante desprendida das ligações terrenas para compreendê-la. Afastam-se, porém, daqueles a quem só a curiosidade impele, ou que, por influência da matéria, fogem à prática do bem. Quando, por exceção, encarnam na Terra, é para cumprir missão de progresso e então nos oferecem o tipo da perfeição a que a Humanidade pode aspirar neste mundo.', 'rascunho'),
  (112, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Caracteres gerais.', 'Nenhuma influência da matéria. Superioridade intelectual e moral absoluta, com relação aos Espíritos das outras ordens.', 'rascunho'),
  (113, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Primeira classe. classe única.', 'Os Espíritos que a compõem percorreram todos os graus da escala e se despojaram de todas as impurezas da matéria. Tendo alcançado a soma de perfeição de que é suscetível a criatura, não têm mais que sofrer provas, nem expiações. Não estando mais sujeitos à reencarnação em corpos perecíveis, realizam a vida eterna no seio de Deus. Gozam de inalterável felicidade, porque não se acham submetidos às necessidades, nem às vicissitudes da vida material. Essa felicidade, porém, não é a de ociosidade monótona, a transcorrer em perpétua contemplação. Eles são os mensageiros e os ministros de Deus, cujas ordens executam para manutenção da harmonia universal. Comandam a todos os Espíritos que lhes são inferiores, auxiliam-nos na obra de seu aperfeiçoamento e lhes designam as suas missões. Assistir os homens nas suas aflições, concitá-los ao bem ou à expiação das faltas que os conservam distanciados da suprema felicidade, constitui para eles ocupação gratíssima. São designados às vezes pelos nomes de anjos, arcanjos ou serafins. Podem os homens pôr-se em comunicação com eles, mas extremamente presunçoso seria aquele que pretendesse tê-los constantemente às suas ordens. 72 – Allan Kar dec', 'rascunho'),
  (114, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os Espíritos são bons ou maus por natureza, ou são eles mesmos que se melhoram?', 'São os próprios Espíritos que se melhoram e, melhorando-se, passam de uma ordem inferior para outra mais elevada.', 'rascunho'),
  (115, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Dos Espíritos, uns terão sido criados bons e outros maus?', 'Deus criou todos os Espíritos simples e ignorantes, isto é, sem saber. A cada um deu determinada missão, com o fim de esclarecê-los e de os fazer chegar progressivamente à perfeição, pelo conhecimento da verdade, para aproximá-los de si. Nesta perfeição é que eles encontram a pura e eterna felicidade. Passando pelas provas que Deus lhes impõe é que os Espíritos adquirem aquele conhecimento. Uns aceitam submissos essas provas e chegam mais depressa à meta que lhes foi assinada. Outros, só a suportam murmurando e, pela falta em que desse modo incorrem, permanecem afastados da perfeição e da prometida felicidade." a) — Segundo o que acabais de dizer, os Espíritos, em sua origem, seriam como as crianças, ignorantes e inexperientes, só adquirindo pouco a pouco os conhecimentos de que carecem com o percorrerem as diferentes fases da vida? "Sim, a comparação é boa. A criança rebelde se conserva ignorante e imperfeita. Seu aproveitamento depende da sua maior ou menor docilidade. Mas, a vida do homem tem termo, ao passo que a dos Espíritos se prolonga ao infinito.', 'rascunho'),
  (116, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Haverá Espíritos que se conservem eternamente nas ordens inferiores?', 'Não; todos se tornarão perfeitos. Mudam de ordem, mas demoradamente, porquanto, como já doutra vez dissemos, um pai justo e misericordioso não pode banir seus filhos para sempre. Pretenderias que Deus, tão grande, tão bom, tão justo, fosse pior do que vós mesmos?', 'rascunho'),
  (117, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Depende dos Espíritos o progredirem mais ou menos rapidamente para a perfeição?', 'Certamente. Eles a alcançam mais ou menos rápido, conforme o desejo que têm de alcançá-la e a submissão que testemunham à vontade de Deus. Uma criança dócil não se instrui mais depressa do que outra recalcitrante?', 'rascunho'),
  (118, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Podem os Espíritos degenerar?', 'Não; à medida que avançam, compreendem o que os distanciava da perfeição. Concluindo uma prova, o Espírito fica com a ciência que daí lhe veio e não a esquece. Pode permanecer estacionário, mas não retrograda.', 'rascunho'),
  (119, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Não podia Deus isentar os Espíritos das provas que lhes cumpre sofrer para chegarem à primeira ordem?', 'Se Deus os houvesse criado perfeitos, nenhum mérito teriam para gozar dos benefícios dessa perfeição. Onde estaria o merecimento sem a luta? Demais, a desigualdade entre eles existente é necessária às suas personalidades. Acresce ainda que as missões que desempenham nos diferentes graus da escala estão nos desígnios da Providência, para a harmonia do Universo." Pois que, na vida social, todos os homens podem chegar às mais altas funções, seria o caso de perguntar-se por que o soberano de um país não faz de cada um de seus soldados um general; por que todos os empregados subalternos não são funcionários superiores; por que todos os colegiais não são mestres. Ora, entre a vida social e a espiritual há esta diferença: enquanto que a primeira é limitada e nem sempre permite que o homem suba todos os seus degraus, a segunda é indefinida e a todos oferece a possibilidade de se elevarem ao grau supremo.', 'rascunho'),
  (120, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Todos os Espíritos passam pela fieira do mal para chegar ao bem?', 'Pela fieira do mal, não; pela fieira da ignorância.', 'rascunho'),
  (121, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Por que é que alguns Espíritos seguiram o caminho do bem e outros o do mal?', 'Não têm eles o livre-arbítrio? Deus não os criou maus; criou-os simples e ignorantes, isto é, tendo tanta aptidão para o bem quanta para o mal. Os que são maus, assim se tornaram por vontade própria.', 'rascunho'),
  (122, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Como podem os Espíritos, em sua origem, quando ainda não têm consciência de si mesmos, gozar da liberdade de escolha entre o bem e o mal? Há neles algum princípio, qualquer tendência que os encaminhe para uma senda de preferência a outra?', 'O livre-arbítrio se desenvolve à medida que o Espírito adquire a consciência de si mesmo. Já não haveria liberdade, desde que a escolha fosse determinada por uma causa independente da vontade do Espírito. A causa não está nele, está fora dele, nas influências a que cede em virtude da sua livre vontade. É o que se contém na grande figura emblemática da queda do homem e do pecado original: uns cederam à tentação, outros resistiram." a) — Donde vêm as influências que sobre ele se exercem? "Dos Espíritos imperfeitos, que procuram apoderar-se dele, dominá-lo, e que rejubilam com o fazê-lo sucumbir. Foi isso o que se intentou simbolizar na figura de Satanás." b) — Tal influência só se exerce sobre o Espírito em sua origem? "Acompanha-o na sua vida de Espírito, até que haja conseguido tanto império sobre si mesmo, que os maus desistem de obsidiá-lo.', 'rascunho'),
  (123, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Por que há Deus permitido que os Espíritos possam tomar o caminho do mal?', 'Como ousais pedir a Deus contas de seus atos? Supondes poder penetrar- lhe os desígnios? Podeis, todavia, dizer o seguinte: A sabedoria de Deus está na liberdade de escolher que ele deixa a cada um, porquanto, assim, cada um tem o mérito de suas obras." 74 – Allan Kar dec', 'rascunho'),
  (124, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Pois que há Espíritos que desde o princípio seguem o caminho do bem absoluto e outros o do mal absoluto, deve haver, sem dúvida, gradações entre esses dois extremos. Não?', 'Sim, certamente, e os que se acham nos graus intermédios constituem a maioria.', 'rascunho'),
  (125, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os Espíritos que enveredaram pela senda do mal poderão chegar ao mesmo grau de superioridade que os outros?', 'Sim; mas as eternidades lhes serão mais longas." Por estas palavras — as eternidades — se deve entender a idéia que os Espíritos inferiores fazem da perpetuidade de seus sofrimentos, cujo termo não lhes é dado ver, idéia que revive todas as vezes que sucumbem numa prova.', 'rascunho'),
  (126, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Chegados ao grau supremo da perfeição, os Espíritos que andaram pelo caminho do mal têm, aos olhos de Deus, menos mérito do que os outros?', 'Deus olha de igual maneira para os que se transviaram e para os outros e a todos ama com o mesmo coração. Aqueles são chamados maus, porque sucumbiram. Antes, não eram mais que simples Espíritos.', 'rascunho'),
  (127, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os Espíritos são criados iguais quanto às faculdades intelectuais?', 'São criados iguais, porém, não sabendo donde vêm, preciso é que o livre- arbítrio siga seu curso. Eles progridem mais ou menos rapidamente em inteligência como em moralidade." Os Espíritos que desde o princípio seguem o caminho do bem nem por isso são Espíritos perfeitos. Não têm, é certo, maus pendores, mas precisam adquirir a experiência e os conhecimentos indispensáveis para alcançar a perfeição. Podemos compará-los a crianças que, seja qual for a bondade de seus instintos naturais, necessitam de se desenvolver e esclarecer e que não passam, sem transição, da infância à madureza. Simplesmente, assim como há homens que são bons e outros que são maus desde a infância, também há Espíritos que são bons ou maus desde a origem, com a diferença capital de que a criança tem instintos já inteiramente formados, enquanto que o Espírito, ao formar-se, não é nem bom, nem mau; tem todas as tendências e toma uma ou outra direção, por efeito do seu livre-arbítrio.', 'rascunho'),
  (128, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os seres a que chamamos anjos, arcanjos, serafins, formam uma categoria especial, de natureza diferente da dos outros Espíritos?', 'Não; são os Espíritos puros: os que se acham no mais alto grau da escala e reúnem todas as perfeições." A palavra anjo desperta geralmente a idéia de perfeição moral. Entretanto, ela se aplica muitas vezes à designação de todos os seres, bons e maus, que estão fora da Humanidade. Diz-se: o anjo bom e o anjo mau; o anjo de luz e o anjo das trevas. Neste caso, o termo é sinônimo de Espírito ou de gênio. Tomamo-lo aqui na sua melhor acepção.', 'rascunho'),
  (129, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Os anjos hão percorrido todos os graus da escala?', 'Percorreram todos os graus, mas do modo que havemos dito: uns, aceitando sem murmurar suas missões, chegaram depressa; outros, gastaram mais ou menos tempo para chegar à perfeição.', 'rascunho'),
  (130, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Sendo errônea a opinião dos que admitem a existência de seres criados perfeitos e superiores a todas as outras criaturas, como se explica que essa crença esteja na tradição de quase todos os povos?', 'Fica sabendo que o mundo onde te achas não existe de toda a eternidade e que, muito tempo antes que ele existisse, já havia Espíritos que tinham atingido o grau supremo. Acreditaram os homens que eles eram assim desde todos os tempos.', 'rascunho'),
  (131, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo I — Dos Espíritos', 'Há demônios, no sentido que se dá a esta palavra?', 'Se houvesse demônios, seriam obra de Deus. Mas, porventura, Deus seria justo e bom se houvera criado seres destinados eternamente ao mal e a permanecerem eternamente desgraçados? Se há demônios, eles se encontram no mundo inferior em que habitais e em outros semelhantes. São esses homens hipócritas que fazem de um Deus justo um Deus mau e vingativo e que julgam agradá-lo por meio das abominações que praticam em seu nome." A palavra demônio não implica a idéia de Espírito mau, senão na sua acepção moderna, porquanto o termo grego daïmon, donde ela derivou, significa gênio, inteligência e se aplicava aos seres incorpóreos, bons ou maus, indistintamente. Por demônios, segundo a acepção vulgar da palavra, se entendem seres essencialmente malfazejos. Como todas as coisas, eles teriam sido criados por Deus. Ora, Deus, que é soberanamente justo e bom, não pode ter criado seres prepostos, por sua natureza, ao mal e condenados por toda a eternidade. Se não fossem obra de Deus, existiriam, como ele, desde toda a eternidade, ou então haveria muitas potências soberanas. A primeira condição de toda doutrina é ser lógica. Ora, à dos demônios, no sentido absoluto, falta esta base essencial. Concebe-se que povos atrasados, os quais, por desconhecerem os atributos de Deus, admitem em suas crenças divindades maléficas, também admitam demônios; mas, é ilógico e contraditório que quem faz da bondade um dos atributos essenciais de Deus suponha haver ele criado seres destinados ao mal e a praticá-lo perpetuamente, porque isso equivale a lhe negar a bondade. Os partidários dos demônios se apóiam nas palavras do Cristo. Não seremos nós quem conteste a autoridade de seus ensinos, que desejáramos ver mais no coração do que na boca dos homens; porém, estarão aqueles partidários certos do sentido que ele dava a esse vocábulo? Não é sabido que a forma alegórica constitui um dos caracteres distintivos da sua linguagem? Dever-se-á tomar ao pé da letra tudo o que o Evangelho contém? Não precisamos de outra prova além da que nos fornece esta passagem: " Logo após esses dias de aflição, o Sol escurecerá e a Lua não mais dará sua luz, as estrelas cairão do céu e as potências do céu se abalarão. Em verdade vos digo que esta geração não passará, sem que todas estas coisas se tenham cumprido" Não temos visto a Ciência contraditar a forma do texto bíblico, no tocante à Criação e ao movimento da Terra? Não se dará o mesmo com algumas figuras de que se serviu o Cristo, que tinha de falar de acordo com os tempos e os lugares? Não é possível que ele haja dito conscientemente uma falsidade. Assim, pois, se nas suas palavras há coisas que parecem chocar a razão, é que não as compreendemos bem, ou as interpretamos mal. 76 – Allan Kar dec Os homens fizeram com os demônios o que fizeram com os anjos. Como acreditaram na existência de seres perfeitos desde toda a eternidade, tomaram os Espíritos inferiores por seres perpetuamente maus. Por demônios se devem entender os Espíritos impuros, que muitas vezes não valem mais do que as entidades designadas por esse nome, mas com a diferença de ser transitório o estado deles. São Espíritos imperfeitos, que se rebelam contra as provas que lhes tocam e que, por isso, as sofrem mais longamente, porém que, a seu turno, chegarão a sair daquele estado, quando o quiserem. Poder-se-ia, pois, aceitar o termo demônio com esta restrição. Como o entendem atualmente, dando-se-lhe um sentido exclusivo, ele induziria em erro, com o fazer crer na existência de seres especiais criados para o mal. Satanás é evidentemente a personificação do mal sob forma alegórica, visto não se poder admitir que exista um ser mau a lutar, como de potência a potência, com a Divindade e cuja única preocupação consistisse em lhe contrariar os desígnios. Como precisa de figuras e imagens que lhe impressionem a imaginação, o homem pintou os seres incorpóreos sob uma forma material, com atributos que lembram as qualidades ou os defeitos humanos. É assim que os antigos, querendo personificar o Tempo, o pintaram com a figura de um velho munido de uma foice e uma ampulheta. Representá-lo pela figura de um mancebo fora contra-senso. O mesmo se verifica com as alegorias da fortuna, da verdade, etc. Os modernos representaram os anjos, os puros Espíritos, por uma figura radiosa, de asas brancas, emblema da pureza; e Satanás com chifres, garras e os atributos da animalidade, emblema das paixões vis. O vulgo, que toma as coisas ao pé da letra, viu nesses emblemas individualidades reais, como vira outrora Saturno na alegoria do Tempo.', 'rascunho'),
  (132, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Qual o objetivo da encarnação dos Espíritos?', 'Deus lhes impõe a encarnação com o fim de fazê-los chegar à perfeição. Para uns, é expiação; para outros, missão. Mas, para alcançarem essa perfeição, têm que sofrer todas as vicissitudes da existência corporal: nisso é que está a expiação. Visa ainda outro fim a encarnação: o de pôr o Espírito em condições de suportar a parte que lhe toca na obra da criação. Para executá-la é que, em cada mundo, toma o Espírito um instrumento, de harmonia com a matéria essencial desse mundo, a fim de aí cumprir, daquele ponto de vista, as ordens de Deus. É assim que, concorrendo para a obra geral, ele próprio se adianta." A ação dos seres corpóreos é necessária à marcha do Universo. Deus, porém, na sua sabedoria, quis que nessa mesma ação eles encontrassem um meio de progredir e de se aproximar dele. Deste modo, por uma admirável lei da Providência, tudo se encadeia, tudo é solidário na Natureza.', 'rascunho'),
  (133, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Têm necessidade de encarnação os Espíritos que, desde o princípio, seguiram o caminho do bem?', 'Todos são criados simples e ignorantes e se instruem nas lutas e tribulações da vida corporal. Deus, que é justo, não podia fazer felizes a uns, sem fadigas e trabalhos, conseguintemente sem mérito." a) — Mas, então, de que serve aos Espíritos terem seguido o caminho do bem, se isso não os isenta dos sofrimentos da vida corporal? "Chegam mais depressa ao fim. Demais, as aflições da vida são muitas vezes a conseqüência da imperfeição do Espírito. Quanto menos imperfeições, tanto menos tormentos. Aquele que não é invejoso, nem ciumento, nem avaro, nem ambicioso, não sofrerá as torturas que se originam desses defeitos." 78 – Allan Kar dec', 'rascunho'),
  (134, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Que é a alma?', 'Um Espírito encarnado." a) — Que era a alma antes de se unir ao corpo? "Espírito." b) — As almas e os Espíritos são, portanto, idênticos, a mesma coisa? "Sim, as almas não são senão os Espíritos. Antes de se unir ao corpo, a alma é um dos seres inteligentes que povoam o mundo invisível, os quais temporariamente revestem um invólucro carnal para se purificarem e esclarecerem.', 'rascunho'),
  (135, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Há no homem alguma outra coisa além da alma e do corpo?', 'Há o laço que liga a alma ao corpo." a) — De que natureza é esse laço? "Semimaterial, isto é, de natureza intermédia entre o Espírito e o corpo. É preciso que seja assim para que os dois se possam comunicar um com o outro. Por meio desse laço é que o Espírito atua sobre a matéria e reciprocamente." O homem é, portanto, formado de três partes essenciais: 1º — o corpo ou ser material, análogo ao dos animais e animado pelo mesmo princípio vital; 2º — a alma, Espírito encarnado que tem no corpo a sua habitação; 3º — o princípio intermediário, ou perispírito, substância semimaterial que serve de primeiro envoltório ao Espírito e liga a alma ao corpo. Tal, num fruto, o gérmen, o perisperma e a casca.', 'rascunho'),
  (136, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'A alma independe do princípio vital?', 'O corpo não é mais do que envoltório, repetimo-lo constantemente." a) — Pode o corpo existir sem a alma? "Pode; entretanto, desde que cessa a vida do corpo, a alma o abandona. Antes do nascimento, ainda não há união definitiva entre a alma e o corpo; enquanto que, depois de essa união se haver estabelecido, a morte do corpo rompe os laços que o prendem à alma e esta o abandona. A vida orgânica pode animar um corpo sem alma, mas a alma não pode habitar um corpo privado de vida orgânica." b) — Que seria o nosso corpo, se não tivesse alma? "Simples massa de carne sem inteligência, tudo o que quiserdes, exceto um homem.', 'rascunho'),
  (137, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Um Espírito pode encarnar a um tempo em dois corpos diferentes?', 'Não, o Espírito é indivisível e não pode animar simultaneamente dois seres distintos." (Ver, em O Livro dos Médiuns, o capítulo VII, " Da bicorporeidade e da tr a nsfigur açã o".)', 'rascunho'),
  (138, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Que se deve pensar da opinião dos que consideram a alma o princípio da vida material?', 'É uma questão de palavras, com que nada temos. Começai por vos entenderdes mutuamente.', 'rascunho'),
  (139, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Alguns Espíritos e, antes deles, alguns filósofos definiram a alma como sendo:', 'uma centelha anímica emanada do grande Todo". Por que essa contradição? "Não há contradição. Tudo depende das acepções das palavras. Por que não tendes uma palavra para cada coisa?" O vocábulo alma se emprega para exprimir coisas muito diferentes. Uns chamam alma ao princípio da vida e, nesta acepção, se pode com acerto dizer, figuradamente, que a alma é uma centelha anímica emanada do grande Todo. Estas últimas palavras indicam a fonte universal do princípio vital de que cada ser absorve uma porção e que, após a morte, volta à massa donde saiu. Essa idéia de nenhum modo exclui a de um ser moral, distinto, independente da matéria e que conserva sua individualidade. A esse ser, igualmente, se dá o nome de alma e nesta acepção é que se pode dizer que a alma é um Espírito encarnado. Dando da alma definições diversas, os Espíritos falaram de acordo com o modo por que aplicavam a palavra e com as idéias terrenas de que ainda estavam mais ou menos imbuídos. Isto resulta da deficiência da linguagem humana, que não dispõe de uma palavra para cada idéia, donde uma imensidade de equívocos e discussões. Eis por que os Espíritos superiores nos dizem que primeiro nos entendamos acerca das palavras.5', 'rascunho'),
  (140, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Que se deve pensar da teoria da alma subdividida em tantas partes quantos são os músculos e presidindo assim a cada uma das funções do corpo?', 'Ainda isto depende do sentido que se empreste à palavra alma. Se se entende por alma o fluido vital, essa teoria tem razão de ser; se se entende por alma o Espírito encarnado, é errônea. Já dissemos que o Espírito é indivisível. Ele imprime movimento aos órgãos, servindo-se do fluido intermediário, sem que para isso se divida." a) — Entretanto, alguns Espíritos deram essa definição. "Os Espíritos ignorantes podem tomar o efeito pela causa." A alma atua por intermédio dos órgãos e os órgãos são animados pelo fluido vital, que por eles se reparte, existindo em maior abundância nos que são centros ou focos de movimento. Esta explicação, porém, não procede, desde que se considere a alma como sendo o Espírito que habita o corpo durante a vida e o deixa por ocasião da morte.', 'rascunho'),
  (141, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Há alguma coisa de verdadeiro na opinião dos que pretendem que a alma é exterior ao corpo e o circunvolve?', 'A alma não se acha encerrada no corpo, qual pássaro numa gaiola. Irradia e se manifesta exteriormente, como a luz através de um globo de vidro, ou como o som em torno de um centro de sonoridade. Neste sentido se pode dizer que ela é exterior, sem que por isso constitua o envoltório do corpo. A alma tem dois invólucros. Um, sutil e leve: é o primeiro, ao qual chamas perispírito; outro, 5 Ver, na Int r odução, a explicação sobre o termo alma, § II. 80 – Allan Kar dec grosseiro, material e pesado, o corpo. A alma é o centro de todos os envoltórios, como o gérmen em um núcleo, já o temos dito.', 'rascunho'),
  (142, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Que dizeis dessa outra teoria segundo a qual a alma, numa criança, se vai completando a cada período da vida?', 'O Espírito é uno e está todo na criança, como no adulto. Os órgãos, ou instrumentos das manifestações da alma, é que se desenvolvem e completam. Ainda aí tomam o efeito pela causa.', 'rascunho'),
  (143, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Por que todos os Espíritos não definem do mesmo modo a alma?', 'Os Espíritos não se acham todos esclarecidos igualmente sobre estes assuntos. Há Espíritos de inteligência ainda limitada, que não compreendem as coisas abstratas. São como as crianças entre vós. Também há Espíritos pseudo- sábios, que fazem alarde de palavras, para se imporem, ainda como sucede entre vós. Depois, os próprios Espíritos esclarecidos podem exprimir-se em termos diferentes, cujo valor, entretanto, é, substancialmente, o mesmo, sobretudo quando se trata de coisas que a vossa linguagem se mostra impotente para traduzir com clareza. Recorrem então a figuras, a comparações, que tomais como realidade.', 'rascunho'),
  (144, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Que se deve entender por alma do mundo?', 'O princípio universal da vida e da inteligência, do qual nascem as individualidades. Mas, os que se servem dessa expressão não se compreendem, as mais das vezes, uns aos outros. O termo alma é tão elástico que cada um o interpreta ao sabor de suas fantasias. Também à Terra hão atribuído uma alma. Por alma da Terra se deve entender o conjunto dos Espíritos abnegados, que dirigem para o bem as vossas ações, quando os escutais, e que, de certo modo, são os lugares-tenentes de Deus com relação ao vosso planeta.', 'rascunho'),
  (145, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Como se explica que tantos filósofos antigos e modernos, durante tão longo tempo, hajam discutido sobre a ciência psicológica e não tenham chegado ao conhecimento da verdade?', 'Esses homens eram os precursores da eterna Doutrina Espírita. Prepararam os caminhos. Eram homens e, como tais, se enganaram, tomando suas próprias idéias pela luz. No entanto, mesmo os seus erros servem para realçar a verdade, mostrando o pró e o contra. Demais, entre esses erros se encontram grandes verdades que um estudo comparativo torna apreensíveis.', 'rascunho'),
  (146, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'A alma tem, no corpo, sede determinada e circunscrita?', 'Não; porém, nos grandes gênios, em todos os que pensam muito, ela reside mais particularmente na cabeça, ao passo que ocupa principalmente o coração naqueles que muito sentem e cujas ações têm todas por objeto a Humanidade." a) — Que se deve pensar da opinião dos que situam a alma num centro vital? "Quer isso dizer que o Espírito habita de preferência essa parte do vosso organismo, por ser aí o ponto de convergência de todas as sensações. Os que a situam no que consideram o centro da vitalidade, esses a confundem com o fluido ou princípio vital. Pode, todavia, dizer-se que a sede da alma se encontra especialmente nos órgãos que servem para as manifestações intelectuais e morais.', 'rascunho'),
  (147, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Por que é que os anatomistas, os fisiologistas e, em geral, os que aprofundam a ciência da Natureza, são, com tanta freqüência, levados ao materialismo?', 'O fisiologista refere tudo ao que vê. Orgulho dos homens, que julgam saber tudo e não admitem haja coisa alguma que lhes esteja acima do entendimento. A própria ciência que cultivam os enche de presunção. Pensam que a Natureza nada lhes pode conservar oculto.', 'rascunho'),
  (148, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo II — Da encarnação dos Espíritos', 'Não é de lastimar que o materialismo seja uma conseqüência de estudos que deveriam, contrariamente, mostrar ao homem a superioridade da inteligência que governa o mundo? Deve-se daí concluir que são perigosos?', 'Não é exato que o materialismo seja uma conseqüência desses estudos. O homem é que deles tira uma conseqüência falsa, pela razão de lhe ser dado abusar de tudo, mesmo das melhores coisas. Acresce que o nada os amedronta mais do que eles quereriam que parecesse, e os espíritos fortes, quase sempre, são antes fanfarrões do que bravos. Na sua maioria, só são materialistas porque não têm com que encher o vazio do abismo que diante deles se abre. Mostrai-lhes uma âncora de salvação e a ela se agarrarão pressurosamente." Por uma aberração da inteligência, pessoas há que só vêem nos seres orgânicos a ação da matéria e a esta atribuem todos os nossos atos. No corpo humano apenas vêem a máquina elétrica; somente pelo funcionamento dos órgãos estudaram o mecanismo da vida, cuja repetida extinção observaram, por efeito da ruptura de um fio, e nada mais enxergaram além desse fio. Procuraram saber se alguma coisa restava e, como nada acharam senão matéria, que se tornara inerte, como não viram a alma escapar-se, como não a puderam apanhar, concluíram que tudo se continha nas propriedades da matéria e que, portanto, à morte se seguia a aniquilação do pensamento. Triste conseqüência, se fora real, porque então o bem e o mal nada significariam, o homem teria razão para só pensar em si e para colocar acima de tudo a satisfação de seus apetites materiais; quebrados estariam os laços sociais e as mais santas afeições se romperiam para sempre. Felizmente, longe estão de ser gerais semelhantes idéias, que se podem mesmo ter por muito circunscritas, constituindo apenas opiniões individuais, pois que em parte alguma ainda formaram doutrina. Uma sociedade que se fundasse sobre tais bases traria em si o gérmen de sua dissolução e seus membros se entredevorariam como animais ferozes. O homem tem, instintivamente, a convicção de que nem tudo se lhe acaba com a vida. O nada lhe infunde horror. É em vão que se obstina contra a idéia da vida futura. Ao soar o momento supremo, poucos são os que não inquirem do que vai ser deles, porque a idéia de deixar a vida para sempre algo oferece de pungente. Quem, de fato, poderia encarar com indiferença uma separação absoluta, eterna, de tudo o que foi objeto de seu amor? Quem poderia ver, sem terror, abrir-se diante si o imensurável abismo do nada, onde se sepultassem para sempre todas as suas faculdades, todas as suas esperanças, e dizer a si mesmo: Pois que! depois de mim, nada, nada mais, senão o vácuo, tudo definitivamente acabado; mais alguns dias e a minha lembrança se terá apagado da memória dos que me 82 – Allan Kar dec sobreviverem; nenhum vestígio, dentro em pouco, restará da minha passagem pela Terra; até mesmo o bem que fiz será esquecido pelos ingratos a quem beneficiei. E nada, para compensar tudo isto, nenhuma outra perspectiva, além da do meu corpo roído pelos vermes! Não tem este quadro alguma coisa de horrível, de glacial? A religião ensina que não pode ser assim e a razão no-lo confirma. Mas, uma existência futura, vaga e indefinida não apresenta o que satisfaça ao nosso desejo do positivo. Essa, em muitos, a origem da dúvida. Possuímos alma, está bem; mas, que é a nossa alma? Tem forma, uma aparência qualquer? É um ser limitado, ou indefinido? Dizem alguns que é um sopro de Deus, outros uma centelha, outros uma parcela do grande Todo, o princípio da vida e da inteligência. Que é, porém, o que de tudo isto ficamos sabendo? Que nos importa ter uma alma, se, extinguindo-se-nos a vida, ela desaparece na imensidade, como as gotas dágua no Oceano? A perda da nossa individualidade não equivale, para nós, ao nada? Diz-se também que a alma é imaterial. Ora, uma coisa imaterial carece de proporções determinadas. Desde então, nada é, para nós. A religião ainda nos ensina que seremos felizes ou desgraçados, conforme ao bem ou ao mal que houvermos feito. Que vem a ser, porém, essa felicidade que nos aguarda no seio de Deus? Será uma beatitude, uma contemplação eterna, sem outra ocupação mais do que entoar louvores ao Criador? As chamas do inferno serão uma realidade ou um símbolo? A própria Igreja lhes dá esta última significação; mas, então, que são aqueles sofrimentos? Onde esse lugar de suplício? Numa palavra, que é o que se faz, que é o que se vê, nesse outro mundo que a todos nos espera? Dizem que ninguém jamais voltou de lá para nos dar informações. É erro dizê-lo e a missão do Espiritismo consiste precisamente em nos esclarecer acerca desse futuro, em fazer com que, até certo ponto, o toquemos com o dedo e o penetremos com o olhar, não mais pelo raciocínio somente, porém, pelos fatos. Graças às comunicações espíritas, não se trata mais de uma simples presunção, de uma probabilidade sobre a qual cada um conjeture à vontade, que os poetas embelezem com suas ficções, ou cumulem de enganadoras imagens alegóricas. É a realidade que nos aparece, pois que são os próprios seres de além-túmulo que nos vêm descrever a situação em que se acham, relatar o que fazem, facultando-nos assistir, por assim dizer, a todas as peripécias da nova vida que lá vivem e mostrando-nos, por esse meio, a sorte inevitável que nos está reservada, de acordo com os nossos méritos e deméritos. Haverá nisso alguma coisa de anti-religioso? Muito ao contrário, porquanto os incrédulos encontram aí a fé e os tíbios a renovação do fervor e da confiança. O Espiritismo é, pois, o mais potente auxiliar da religião. Se ele aí está, é porque Deus o permite e o permite para que as nossas vacilantes esperanças se revigorem e para que sejamos reconduzidos à senda do bem pela perspectiva do futuro.', 'rascunho'),
  (149, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'Que sucede à alma no instante da morte?', 'Volta a ser Espírito, isto é, volve ao mundo dos Espíritos, donde se apartara momentaneamente.', 'rascunho'),
  (150, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'A alma, após a morte, conserva a sua individualidade?', 'Sim; jamais a perde. Que seria ela, se não a conservasse?" a) — Como comprova a alma a sua individualidade, uma vez que não tem mais corpo material? "Continua a ter um fluido que lhe é próprio, haurido na atmosfera do seu planeta, e que guarda a aparência de sua última encarnação: seu perispírito." b) — A alma nada leva consigo deste mundo? "Nada, a não ser a lembrança e o desejo de ir para um mundo melhor, lembrança cheia de doçura ou de amargor, conforme o uso que ela fez da vida. Quanto mais pura for, melhor compreenderá a futilidade do que deixa na Terra.', 'rascunho'),
  (151, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'Que pensar da opinião dos que dizem que após a morte a alma retorna ao todo universal?', 'O conjunto dos Espíritos não forma um todo? Não constitui um mundo completo? Quando estás numa assembléia, és parte integrante dela; mas, não obstante, conservas sempre a tua individualidade.', 'rascunho'),
  (152, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'Que prova podemos ter da individualidade da alma depois da morte?', 'Não tendes essa prova nas comunicações que recebeis? Se não fôsseis cegos, veríeis; se não fôsseis surdos, ouviríeis; pois que muito amiúde uma voz vos fala, reveladora da existência de um ser que está fora de vós." 84 – Allan Kar dec Os que pensam que, pela morte, a alma reingressa no todo universal estão em erro, se supõem que, semelhante à gota dágua que cai no Oceano, ela perde ali a sua individualidade. Estão certos, se por todo universal entendem o conjunto dos seres incorpóreos, conjunto de que cada alma ou Espírito é um elemento. Se as almas se confundissem num amálgama só teriam as qualidades do conjunto, nada as distinguiria umas das outras. Careceriam de inteligência e de qualidades pessoais quando, ao contrário, em todas as comunicações, denotam ter consciência do seu eu e vontade própria. A diversidade infinita que apresentam, sob todos os aspectos, é a conseqüência mesma de constituírem individualidades diversas. Se, após a morte, só houvesse o que se chama o grande Todo, a absorver todas as individualidades, esse Todo seria uniforme e, então, as comunicações que se recebessem do mundo invisível seriam idênticas. Desde que, porém, lá se nos deparam seres bons e maus, sábios e ignorantes, felizes e desgraçados; que lá os há de todos os caracteres: alegres e tristes, levianos e ponderados, etc., patente se faz que eles são seres distintos. A individualidade ainda mais evidente se torna, quando esses seres provam a sua identidade por indicações incontestáveis, particularidades individuais verificáveis, referentes às suas vidas terrestres. Também não pode ser posta em dúvida, quando se fazem visíveis nas aparições. A individualidade da alma nos era ensinada em teoria, como artigo de fé. O Espiritismo a torna manifesta e, de certo modo, material.', 'rascunho'),
  (153, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'Em que sentido se deve entender a vida eterna?', 'A vida do Espírito é que é eterna; a do corpo é transitória e passageira. Quando o corpo morre, a alma retoma a vida eterna." a) — Não seria mais exato chamar vida eterna à dos Espíritos puros, dos que, tendo atingido a perfeição, não estão sujeitos a sofrer mais prova alguma? "Essa é antes a felicidade eterna. Mas isto constitui uma questão de palavras. Chamai as coisas como quiserdes, contanto que vos entendais.', 'rascunho'),
  (154, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'É dolorosa a separação da alma e do corpo?', 'Não; o corpo quase sempre sofre mais durante a vida do que no momento da morte; a alma nenhuma parte toma nisso. Os sofrimentos que algumas vezes se experimentam no instante da morte são um gozo para o Espírito, que vê chegar o termo do seu exílio." Na morte natural, a que sobrevém pelo esgotamento dos órgãos, em conseqüência da idade, o homem deixa a vida sem o perceber: é uma lâmpada que se apaga por falta de óleo.', 'rascunho'),
  (155, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'Como se opera a separação da alma e do corpo?', 'Rotos os laços que a retinham, ela se desprende." a) — A separação se dá instantaneamente por brusca transição? Haverá alguma linha de demarcação nitidamente traçada entre a vida e a morte? "Não; a alma se desprende gradualmente, não se escapa como um pássaro cativo a que se restitua subitamente a liberdade. Aqueles dois estados se tocam e confundem, de sorte que o Espírito se solta pouco a pouco dos laços que o prendiam. Estes laços se desatam, não se quebram." Durante a vida, o Espírito se acha preso ao corpo pelo seu envoltório semimaterial ou perispírito. A morte é a destruição do corpo somente, não a desse outro invólucro, que do corpo se separa quando cessa neste a vida orgânica. A observação demonstra que, no instante da morte, o desprendimento do perispírito não se completa subitamente; que, ao contrário, se opera gradualmente e com uma lentidão muito variável conforme os indivíduos. Em uns é bastante rápido, podendo dizer-se que o momento da morte é mais ou menos o da libertação. Em outros, naqueles sobretudo cuja vida foi toda material e sensual, o desprendimento é muito menos rápido, durando algumas vezes dias, semanas e até meses, o que não implica existir, no corpo, a menor vitalidade, nem a possibilidade de volver à vida, mas uma simples afinidade com o Espírito, afinidade que guarda sempre proporção com a preponderância que, durante a vida, o Espírito deu à matéria. É, com efeito, racional conceber-se que, quanto mais o Espírito se haja identificado com a matéria, tanto mais penoso lhe seja separar-se dela; ao passo que a atividade intelectual e moral, a elevação dos pensamentos operam um começo de desprendimento, mesmo durante a vida do corpo, de modo que, em chegando a morte, ele é quase instantâneo. Tal o resultado dos estudos feitos em todos os indivíduos que se têm podido observar por ocasião da morte. Essas observações ainda provam que a afinidade, persistente entre a alma e o corpo, em certos indivíduos, é, às vezes, muito penosa, porquanto o Espírito pode experimentar o horror da decomposição. Este caso, porém, é excepcional e peculiar a certos gêneros de vida e a certos gêneros de morte. Verifica-se com alguns, suicidas.', 'rascunho'),
  (156, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'A separação definitiva da alma e do corpo pode ocorrer antes da cessação completa da vida orgânica?', 'Na agonia, a alma, algumas vezes, já tem deixado o corpo; nada mais há que a vida orgânica. O homem já não tem consciência de si mesmo; entretanto, ainda lhe resta um sopro de vida orgânica. O corpo é a máquina que o coração põe em movimento. Existe, enquanto o coração faz circular nas veias o sangue, para o que não necessita da alma.', 'rascunho'),
  (157, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'No momento da morte, a alma sente, alguma vez, qualquer aspiração ou êxtase que lhe faça entrever o mundo onde vai de novo entrar?', 'Muitas vezes a alma sente que se desfazem os laços que a prendem ao corpo. Emprega então todos os esforços para desfazê-los inteiramente. Já em parte desprendida da matéria, vê o futuro desdobrar-se diante de si e goza, por antecipação, do estado de Espírito.', 'rascunho'),
  (158, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'O exemplo da lagarta que, primeiro, anda de rastos pela terra, depois se encerra na sua crisálida em estado de morte aparente, para enfim renascer com uma existência brilhante, pode dar-nos idéia da vida terrestre, do túmulo e, finalmente, da nossa nova existência?', 'Uma idéia acanhada. A imagem é boa; todavia, cumpre não seja tomada ao pé da letra, como freqüentemente vos sucede.', 'rascunho'),
  (159, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'Que sensação experimenta a alma no momento em que reconhece estar no mundo dos Espíritos? 86 – Allan Kar dec', 'Depende. Se praticaste o mal, impelido pelo desejo de o praticar, no primeiro momento te sentirás envergonhado de o haveres praticado. Com a alma do justo as coisas se passam de modo bem diferente. Ela se sente como que aliviada de grande peso, pois que não teme nenhum olhar perscrutador.', 'rascunho'),
  (160, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'O Espírito se encontra imediatamente com os que conheceu na Terra e que morreram antes dele?', 'Sim, conforme à afeição que lhes votava e a que eles lhe consagravam. Muitas vezes aqueles seus conhecidos o vêm receber à entrada do mundo dos Espíritos e o ajudam a desligar-se das faixas da matéria. Encontra-se também com muitos dos que conheceu e perdeu de vista durante a sua vida terrena. Vê os que estão na erraticidade, como vê os encarnados e os vai visitar.', 'rascunho'),
  (161, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'Em caso de morte violenta e acidental, quando os órgãos ainda se não enfraqueceram em conseqüência da idade ou das moléstias, a separação da alma e a cessação da vida ocorrem simultaneamente?', 'Geralmente assim é; mas, em todos os casos, muito breve é o instante que medeia entre uma e outra.', 'rascunho'),
  (162, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'Após a decapitação, por exemplo, conserva o homem por alguns instantes a consciência de si mesmo?', 'Não raro a conserva durante alguns minutos, até que a vida orgânica se tenha extinguido completamente. Mas, também, quase sempre a apreensão da morte lhe faz perder aquela consciência antes do momento do suplício." Trata-se aqui da consciência que o supliciado pode ter de si mesmo, como homem e por intermédio dos órgãos, e não como Espírito. Se não perdeu essa consciência antes do suplício, pode conservá-la por alguns breves instantes. Ela, porém, cessa necessariamente com a vida orgânica do cérebro, o que não quer dizer que o perispírito esteja inteiramente separado do corpo. Ao contrário: em todos os casos de morte violenta, quando a morte não resulta da extinção gradual das forças vitais, mais tenazes os laços que prendem o corpo ao perispírito e, portanto, mais lento o desprendimento completo.', 'rascunho'),
  (163, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'A alma tem consciência de si mesma imediatamente depois de deixar o corpo?', 'Imediatamente não é bem o termo. A alma passa algum tempo em estado de perturbação.', 'rascunho'),
  (164, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'A perturbação que se segue à separação da alma e do corpo é do mesmo grau e da mesma duração para todos os Espíritos?', 'Não; depende da elevação de cada um. Aquele que já está purificado, se reconhece quase imediatamente, pois que se libertou da matéria antes que cessasse a vida do corpo, enquanto que o homem carnal, aquele cuja consciência ainda não está pura, guarda por muito mais tempo a impressão da matéria.', 'rascunho'),
  (165, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo III — Da volta do Espírito, extinta a vida corpórea, à vida espiritual', 'O conhecimento do Espiritismo exerce alguma influência sobre a duração, mais ou menos longa, da perturbação?', 'Influência muito grande, por isso que o Espírito já antecipadamente compreendia a sua situação. Mas, a prática do bem e a consciência pura são o que maior influência exercem." Por ocasião da morte, tudo, a princípio, é confuso. De algum tempo precisa a alma para entrar no conhecimento de si mesma. Ela se acha como que aturdida, no estado de uma pessoa que despertou de profundo sono e procura orientar-se sobre a sua situação. A lucidez das idéias e a memória do passado lhe voltam, à medida que se apaga a influência da matéria que ela acaba de abandonar, e à medida que se dissipa a espécie de névoa que lhe obscurece os pensamentos. Muito variável é o tempo que dura a perturbação que se segue à morte. Pode ser de algumas horas, como também de muitos meses e até de muitos anos. Aqueles que, desde quando ainda viviam na Terra, se identificaram com o estado futuro que os aguardava, são os em quem menos longa ela é, porque esses compreendem imediatamente a posição em que se encontram. Aquela perturbação apresenta circunstâncias especiais, de acordo com os caracteres dos indivíduos e, principalmente, com o gênero de morte. Nos casos de morte violenta, por suicídio, suplício, acidente, apoplexia, ferimentos, etc., o Espírito fica surpreendido, espantado e não acredita estar morto. Obstinadamente sustenta que não o está. No entanto, vê o seu próprio corpo reconhece que esse corpo é seu, mas não compreende que se ache separado dele. Acerca-se das pessoas a quem estima, fala-lhes e não percebe por que elas não o ouvem. Semelhante ilusão se prolonga até ao completo desprendimento do perispírito. Só então o Espírito se reconhece como tal e compreende que não pertence mais ao número dos vivos. Este fenômeno se explica facilmente. Surpreendido de improviso pela morte, o Espírito fica atordoado com a brusca mudança que nele se operou; considera ainda a morte como sinônimo de destruição, de aniquilamento. Ora, porque pensa, vê, ouve, tem a sensação de não estar morto. Mais lhe aumenta a ilusão o fato de se ver com um corpo semelhante, na forma, ao precedente, mas cuja natureza etérea ainda não teve tempo de estudar. Julga-o sólido e compacto como o primeiro e, quando se lhe chama a atenção para esse ponto, admira-se de não poder palpá-lo. Esse fenômeno é análogo ao que ocorre com alguns sonâmbulos inexperientes, que não crêem dormir. É que têm o sono por sinônimo de suspensão das faculdades. Ora, como pensam livremente e vêem, julgam naturalmente que não dormem. Certos Espíritos revelam essa particularidade, se bem que a morte não lhes tenha sobrevindo inopinadamente. Todavia, sempre mais generalizada se apresenta entre os que, embora doentes, não pensavam em morrer. Observa-se então o singular espetáculo de um Espírito assistir ao seu próprio enterramento como se fora o de um estranho, falando desse ato como de coisa que lhe não diz respeito, até ao momento em que compreende a verdade. A perturbação que se segue à morte nada tem de penosa para o homem de bem, que se conserva calmo, semelhante em tudo a quem acompanha as fases de um tranqüilo despertar. Para aquele cuja consciência ainda não está pura, a perturbação é cheia de ansiedade e de angústias, que aumentam à proporção que ele da sua situação se compenetra. Nos casos de morte coletiva, tem sido observado que todos os que perecem ao mesmo tempo nem sempre tornam a ver-se logo. Presas da perturbação que se segue à morte, cada um vai para seu lado, ou só se preocupa com os que lhe interessam. 88 – Allan Kar dec', 'rascunho'),
  (166, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Como pode a alma, que não alcançou a perfeição durante a vida corpórea, acabar de depurar-se?', 'Sofrendo a prova de uma nova existência." a) — Como realiza essa nova existência? Será pela sua transformação como Espírito? "Depurando-se, a alma indubitavelmente experimenta uma transformação, mas para isso necessária lhe é a prova da vida corporal." b) — A alma passa então por muitas existências corporais? "Sim, todos contamos muitas existências. Os que dizem o contrário pretendem manter-vos na ignorância em que eles próprios se encontram. Esse o desejo deles." c) — Parece resultar desse princípio que a alma, depois de haver deixado um corpo, toma outro, ou, então, que reencarna em novo corpo. É assim que se deve entender? "Evidentemente.', 'rascunho'),
  (167, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Qual o fim objetivado com a reencarnação?', 'Expiação, melhoramento progressivo da Humanidade. Sem isto, onde a justiça?', 'rascunho'),
  (168, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'É limitado o número das existências corporais, ou o Espírito reencarna perpetuamente?', 'A cada nova existência, o Espírito dá um passo para diante na senda do progresso. Desde que se ache limpo de todas as impurezas, não tem mais necessidade das provas da vida corporal.', 'rascunho'),
  (169, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'É invariável o número das encarnações para todos os Espíritos?', 'Não; aquele que caminha depressa, a muitas provas se forra. Todavia, as encarnações sucessivas são sempre muito numerosas, porquanto o progresso é quase infinito.', 'rascunho'),
  (170, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'O que fica sendo o Espírito depois da sua última encarnação?', 'Espírito bem-aventurado; puro Espírito.', 'rascunho'),
  (171, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Em que se funda o dogma da reencarnação?', 'Na justiça de Deus e na revelação, pois incessantemente repetimos: o bom pai deixa sempre aberta a seus filhos uma porta para o arrependimento. Não te diz a razão que seria injusto privar para sempre da felicidade eterna todos aqueles de quem não dependeu o melhorarem-se? Não são filhos de Deus todos os homens? Só entre os egoístas se encontram a iniqüidade, o ódio implacável e os castigos sem remissão." Todos os Espíritos tendem para a perfeição e Deus lhes faculta os meios de alcançá-la, proporcionando-lhes as provações da vida corporal. Sua justiça, porém, lhes concede realizar, em novas existências, o que não puderam fazer ou concluir numa primeira prova. Não obraria Deus com eqüidade, nem de acordo com a sua bondade, se condenasse para sempre os que talvez hajam encontrado, oriundos do próprio meio onde foram colocados e alheios à vontade que os animava, obstáculos ao seu melhoramento. Se a sorte do homem se fixasse irrevogavelmente depois da morte, não seria uma única a balança em que Deus pesa as ações de todas as criaturas e não haveria imparcialidade no tratamento que a todas dispensa. A doutrina da reencarnação, isto é, a que consiste em admitir para o Espírito muitas existências sucessivas, é a única que corresponde à idéia que formamos da justiça de Deus para com os homens que se acham em condição moral inferior; a única que pode explicar o futuro e firmar as nossas esperanças, pois que nos oferece os meios de resgatarmos os nossos erros por novas provações. A razão no-la indica e os Espíritos a ensinam. O homem, que tem consciência da sua inferioridade, haure consoladora esperança na doutrina da reencarnação. Se crê na justiça de Deus, não pode contar que venha a achar- se, para sempre, em pé de igualdade com os que mais fizeram do que ele. Sustém-no, porém, e lhe reanima a coragem a idéia de que aquela inferioridade não o deserda eternamente do supremo bem e que, mediante novos esforços, dado lhe será conquistá-lo. Quem é que, ao cabo da sua carreira, não deplora haver tão tarde ganho uma experiência de que já não mais pode tirar proveito? Entretanto, essa experiência tardia não fica perdida; o Espírito a utilizará em nova existência. 90 – Allan Kar dec', 'rascunho'),
  (172, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'As nossas diversas existências corporais se verificam todas na Terra?', 'Não; vivemo-las em diferentes mundos. As que aqui passamos não são as primeiras, nem as últimas; são, porém, das mais materiais e das mais distantes da perfeição.', 'rascunho'),
  (173, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'A cada nova existência corporal a alma passa de um mundo para outro, ou pode ter muitas no mesmo globo?', 'Pode viver muitas vezes no mesmo globo, se não se adiantou bastante para passar a um mundo superior." a) — Podemos então reaparecer muitas vezes na Terra? "Certamente." b) — Podemos voltar a este, depois de termos vivido em outros mundos? "Sem dúvida. É possível que já tenhais vivido algures e na Terra.', 'rascunho'),
  (174, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Tornar a viver na Terra constitui uma necessidade?', 'Não; mas, se não progredistes, podereis ir para outro mundo que não valha mais do que a Terra e que talvez até seja pior do que ela.', 'rascunho'),
  (175, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Haverá alguma vantagem em voltar-se a habitar a Terra?', 'Nenhuma vantagem particular, a menos que seja em missão, caso em que se progride aí como em qualquer outro planeta." a) — Não se seria mais feliz permanecendo na condição de Espírito? "Não, não; estacionar-se-ia e o que se quer é caminhar para Deus.', 'rascunho'),
  (176, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Depois de haverem encarnado noutros mundos, podem os Espíritos encarnar neste, sem que jamais aí tenham estado?', 'Sim, do mesmo modo que vós em outros. Todos os mundos são solidários: o que não se faz num faz-se noutro." a) — Assim, homens há que estão na Terra pela primeira vez? "Muitos, e em graus diversos de adiantamento." b)— Pode-se reconhecer, por um indício qualquer, que um Espírito está pela primeira vez na Terra? "Nenhuma utilidade teria isso.', 'rascunho'),
  (177, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Para chegar à perfeição e à suprema felicidade, destino final de todos os homens, tem o Espírito que passar pela fieira de todos os mundos existentes no Universo?', 'Não, porquanto muitos são os mundos correspondentes a cada grau da respectiva escala e o Espírito, saindo de um deles, nenhuma coisa nova aprenderia nos outros do mesmo grau." a) — Como se explica então a pluralidade de suas existências em um mesmo globo? "De cada vez poderá ocupar posição diferente das anteriores e nessas diversas posições se lhe deparam outras tantas ocasiões de adquirir experiência.', 'rascunho'),
  (178, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Podem os Espíritos encarnar em um mundo relativamente inferior a outro onde já viveram?', 'Sim, quando em missão, com o objetivo de auxiliarem o progresso, caso em que aceitam alegres as tribulações de tal existência, por lhes proporcionar meio de se adiantarem." a) — Mas, não pode dar-se também por expiação? Não pode Deus degredar para mundos inferiores Espíritos rebeldes? "Os Espíritos podem conservar-se estacionários, mas não retrogradam. Em caso de estacionamento, a punição deles consiste em não avançarem, em recomeçarem, no meio conveniente à sua natureza, as existências mal-empregadas." b) — Quais os que têm de recomeçar a mesma existência? "Os que faliram em suas missões ou em suas provas.', 'rascunho'),
  (179, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Os seres que habitam cada mundo hão todos alcançado o mesmo nível de perfeição?', 'Não; dá-se em cada um o que ocorre na Terra: uns Espíritos são mais adiantados do que outros.', 'rascunho'),
  (180, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Passando deste planeta para outro, conserva o Espírito a inteligência que aqui tinha?', 'Sem dúvida; a inteligência não se perde. Pode, porém, acontecer que ele não disponha dos mesmos meios para manifestá-la, dependendo isto da sua superioridade e das condições do corpo que tomar." (Veja-se: "Influência do organismo",cap. VII, Parte 2ª.)', 'rascunho'),
  (181, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Os seres que habitam os diferentes mundos têm corpos semelhantes aos nossos?', 'É fora de dúvida que têm corpos, porque o Espírito precisa estar revestido de matéria para atuar sobre a matéria. Esse envoltório, porém, é mais ou menos material, conforme o grau de pureza a que chegaram os Espíritos. É isso o que assinala a diferença entre os mundos que temos de percorrer, porquanto muitas moradas há na casa de nosso Pai, sendo, conseguintemente, de muitos graus essas moradas. Alguns o sabem e desse fato têm consciência na Terra; com outros, no entanto, o mesmo não se dá." 92 – Allan Kar dec', 'rascunho'),
  (182, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'É-nos possível conhecer exatamente o estado físico e moral dos diferentes mundos?', 'Nós, Espíritos, só podemos responder de acordo com o grau de adiantamento em que vos achais. Quer dizer que não devemos revelar estas coisas a todos, porque nem todos estão em estado de compreendê-las e semelhante revelação os perturbaria." À medida que o Espírito se purifica, o corpo que o reveste se aproxima igualmente da natureza espírita. Torna-se-lhe menos densa a matéria, deixa de rastejar penosamente pela superfície do solo, menos grosseiras se lhe fazem as necessidades físicas, não mais sendo preciso que os seres vivos se destruam mutuamente para se nutrirem. O Espírito se acha mais livre e tem, das coisas longínquas, percepções que desconhecemos. Vê com os olhos do corpo o que só pelo pensamento entrevemos. Da purificação do Espírito decorre o aperfeiçoamento moral, para os seres que eles constituem, quando encarnados. As paixões animais se enfraquecem e o egoísmo cede lugar ao sentimento da fraternidade. Assim é que, nos mundos superiores ao nosso, se desconhecem as guerras, carecendo de objeto os ódios e as discórdias, porque ninguém pensa em causar dano ao seu semelhante. A intuição que seus habitantes têm do futuro, a segurança que uma consciência isenta de remorsos lhes dá, fazem que a morte nenhuma apreensão lhes cause. Encaram-na de frente, sem temor, como simples transformação. A duração da vida, nos diferentes mundos, parece guardar proporção com o grau de superioridade física e moral de cada um, o que é perfeitamente racional. Quanto menos material o corpo, menos sujeito às vicissitudes que o desorganizam. Quanto mais puro o Espírito, menos paixões a miná-lo. É essa ainda uma graça da Providência, que desse modo abrevia os sofrimentos.', 'rascunho'),
  (183, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Indo de um mundo para outro, o Espírito passa por nova infância?', 'Em toda parte a infância é uma transição necessária, mas não é, em toda parte, tão obtusa como no vosso mundo.', 'rascunho'),
  (184, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Tem o Espírito a faculdade de escolher o mundo onde passe a habitar?', 'Nem sempre. Pode pedir que lhe seja permitido ir para este ou aquele e pode obtê-lo, se o merecer, porquanto a acessibilidade dos mundos, para os Espíritos, depende do grau da elevação destes." a) — Se o Espírito nada pedir, que é o que determina o mundo em que ele reencarnará? "O grau da sua elevação.', 'rascunho'),
  (185, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'O estado físico e moral dos seres vivos é perpetuamente o mesmo em cada mundo?', 'Não; os mundos também estão sujeitos à lei do progresso. Todos começaram, como o vosso, por um estado inferior e a própria Terra sofrerá idêntica transformação. Tornar-se-á um paraíso, quando os homens se houverem tornado bons." É assim que as raças, que hoje povoam a Terra, desaparecerão um dia, substituídas por seres cada vez mais perfeitos, pois que essas novas raças transformadas sucederão às atuais, como estas sucederam a outras ainda mais grosseiras.', 'rascunho'),
  (186, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Haverá mundos onde o Espírito, deixando de revestir corpos materiais, só tenha por envoltório o perispírito?', 'Há e mesmo esse envoltório se torna tão etéreo que para vós é como se não existisse. Esse o estado dos Espíritos puros." a) — Parece resultar daí que, entre o estado correspondente às últimas encarnações e a de Espírito puro, não há linha divisória perfeitamente demarcada; não? "Semelhante demarcação não existe. A diferença entre um e outro estado se vai apagando pouco a pouco e acaba por ser imperceptível, tal qual se dá com a noite às primeiras claridades do alvorecer.', 'rascunho'),
  (187, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'A substância do perispírito é a mesma em todos os mundos?', 'Não; é mais ou menos etérea. Passando de um mundo a outro, o Espírito se reveste da matéria própria desse outro, operando-se, porém, essa mudança com a rapidez do relâmpago.', 'rascunho'),
  (188, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Os Espíritos puros habitam mundos especiais, ou se acham no espaço universal, sem estarem mais ligados a um mundo do que a outros?', 'Habitam certos mundos, mas não lhes ficam presos, como os homens à Terra; podem, melhor do que os outros, estar em toda parte." 6 6 Segundo os Espíritos, de todos os mundos que compõem o nosso sistema planetário, a Ter r a é dos de habitantes menos adiantados, física e moralmente. Marte lhe estaria ainda abaixo, sendo-lhe J úpiter superior de muito, a todos os respeitos. O Sol não seria mundo habitado por seres corpóreos, mas simplesmente um lugar de reunião dos Espíritos superiores, os quais de lá irradiam seus pensamentos para os outros mundos, que eles dirigem por intermédio de Espíritos menos elevados, transmitindo-os a estes por meio do fluido universal. Considerado do ponto de vista da sua constituição física, o Sol seria um foco de eletricidade. Todos os sóis como que estariam em situação análoga. O volume de cada um e a distância a que esteja do Sol nenhuma relação necessária guardam com o grau do seu adiantamento, pois que, do contrário, Vênus deveria ser tida por mais adiantada do que a Terra e Saturno menos do que Júpiter. Muitos Espíritos, que na Terra animaram personalidades conhecidas, disseram estar reencarnados em Júpiter, um dos mundos mais próximos da perfeição, e há causado espanto que, nesse globo tão adiantado, estivessem homens a quem a opinião geral aqui não atribuía tanta elevação. Nisso nada há de surpreendente, desde que se atenda a que, possivelmente, certos Espíritos, habitantes daquele planeta, foram mandados à Terra para desempenharem aí certa missão que, aos nossos olhos, os não colocava na primeira plana. Em segundo lugar, deve-se atender a que, entre a existência que tiveram na Terra e a que passaram a ter em Júpiter, podem eles ter tido outras intermédias, em que se melhoraram. Finalmente, cumpre se considere que, naquele mundo, como no nosso, múltiplos são os graus de desenvolvimento e que, entre esses graus, pode medear lá a distância que vai, entre nós, do selvagem ao homem civilizado. Assim, do fato de um Espírito habitar Júpiter não se segue que esteja no nível dos seres mais adiantados, do mesmo modo que ninguém pode considerar-se na categoria de um sábio do Instituto, só porque reside em Paris. As condições de longevidade não são, tampouco, em qualquer parte, as mesmas que na Terra e as idades não se podem comparar. Evocado, um Espírito que desencarnara havia alguns anos, disse que, desde seis meses antes, estava encarnado em mundo cujo nome nos é desconhecido. Interrogado sobre a idade que tinha nesse mundo, disse: "Não posso avaliá-la, porque não contamos o tempo como contais. Depois, os modos de existência não são idênticos. Nós, lá, nos desenvolvemos muito mais rapidamente. Entretanto, se bem não haja mais de seis dos vossos meses que lá estou, posso dizer que, quanto à inteligência, tenho trinta anos da idade que tive na Terra." Muitas respostas análogas foram dadas por outros Espíritos e o fato nada apresenta de inverossímil. Não vemos que, na Terra, uma imensidade de animais em poucos meses adquire o desenvolvimento normal? Por que não se poderia dar o mesmo com o homem noutras esferas? Notemos, além disso, que o desenvolvimento que o homem alcança na Terra aos trinta anos talvez não passe de uma espécie de infância, comparado com o que lhe cumpre atingir. Bem curto de vista se revela quem nos toma em tudo por protótipos da criação, assim como é rebaixar a Divindade o imaginar-se que, fora o homem, nada mais seja possível a Deus. 94 – Allan Kar dec', 'rascunho'),
  (189, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Desde o início de sua formação, goza o Espírito da plenitude de suas faculdades?', 'Não, pois que para o Espírito, como para o homem, também há infância. Em sua origem, a vida do Espírito é apenas instintiva. Ele mal tem consciência de si mesmo e de seus atos. A inteligência só pouco a pouco se desenvolve.', 'rascunho'),
  (190, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Qual o estado da alma na sua primeira encarnação?', 'O da infância na vida corporal. A inteligência então apenas desabrocha: a alma se ensaia para a vida.', 'rascunho'),
  (191, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'As dos nossos selvagens são almas no estado de infância?', 'De infância relativa, pois já são almas desenvolvidas, visto que já nutrem paixões." a) — Então, as paixões são um sinal de desenvolvimento? "De desenvolvimento, sim; de perfeição, porém, não. São sinal de atividade e de consciência do eu, porquanto, na alma primitiva, a inteligência e a vida se acham no estado de gérmen." A vida do Espírito, em seu conjunto, apresenta as mesmas fases que observamos na vida corporal. Ele passa gradualmente do estado de embrião ao de infância, para chegar, percorrendo sucessivos períodos, ao de adulto, que é o da perfeição, com a diferença de que para o Espírito não há declínio, nem decrepitude, como na vida corporal; que a sua vida, que teve começo, não terá fim; que imenso tempo lhe é necessário, do nosso ponto de vista, para passar da infância espírita ao completo desenvolvimento; e que o seu progresso se realiza, não num único mundo, mas vivendo ele em mundos diversos. A vida do Espírito, pois, se compõe de uma série de existências corpóreas, cada uma das quais representa para ele uma ocasião de progredir, do mesmo modo que cada existência corporal se compõe de uma série de dias, em cada um dos quais o homem obtém um acréscimo de experiência e de instrução. Mas, assim como, na vida do homem, há dias que nenhum fruto produzem, na do Espírito há existências corporais de que ele nenhum resultado colhe, porque não as soube aproveitar.', 'rascunho'),
  (192, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Pode alguém, por um proceder impecável na vida atual, transpor todos os graus da escala do aperfeiçoamento e tornar-se Espírito puro, sem passar por outros graus intermédios?', 'Não, pois o que o homem julga perfeito longe está da perfeição. Há qualidades que lhe são desconhecidas e incompreensíveis. Poderá ser tão perfeito quanto o comporte a sua natureza terrena, mas isso não é a perfeição absoluta. Dá-se com o Espírito o que se verifica com a criança que, por mais precoce que seja, tem de passar pela juventude, antes de chegar à idade da madureza; e também com o enfermo que, para recobrar a saúde, tem que passar pela convalescença. Demais, ao Espírito cumpre progredir em ciência e em moral. Se somente se adiantou num sentido, importa se adiante no outro, para atingir o extremo superior da escala. Contudo, quanto mais o homem se adiantar na sua vida atual, tanto menos longas e penosas lhe serão as provas que se seguirem." a) — Pode ao menos o homem, na vida presente, preparar com segurança, para si, uma existência futura menos prenhe de amarguras? "Sem dúvida. Pode reduzir a extensão e as dificuldades do caminho. Só o descuidoso permanece sempre no mesmo ponto.', 'rascunho'),
  (193, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Pode um homem, nas suas novas existências, descer mais baixo do que esteja na atual?', 'Com relação à posição social, sim; como Espírito, não.', 'rascunho'),
  (194, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'É possível que, em nova encarnação, a alma de um homem de bem anime o corpo de um celerado?', 'Não, visto que não pode degenerar." a) — A alma de um homem perverso pode tornar-se a de um homem de bem? "Sim, se se arrependeu. Isso constitui então uma recompensa." A marcha dos Espíritos é progressiva, jamais retrograda. Eles se elevam gradualmente na hierarquia e não descem da categoria a que ascenderam. Em suas diferentes existências corporais, podem descer como homens, não como Espíritos. Assim, a alma de um potentado da Terra pode mais tarde animar o mais humilde obreiro e vice-versa, por isso que, entre os homens, as categorias estão, freqüentemente, na razão inversa da elevação das qualidades morais. Herodes era rei e Jesus, carpinteiro.', 'rascunho'),
  (195, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'A possibilidade de se melhorarem noutra existência não será de molde a fazer que certas pessoas perseverem no mau caminho, dominadas pela idéia de que poderão corrigir-se mais tarde?', 'Aquele que assim pensa em nada crê e a idéia de um castigo eterno não o refrearia mais do que qualquer outra, porque sua razão a repele, e semelhante idéia induz à incredulidade a respeito de tudo. Se unicamente meios racionais se tivessem empregado para guiar os homens, não haveria tantos cépticos. De fato, um Espírito imperfeito poderá, durante a vida corporal, pensar como dizes; mas, liberto que se veja da matéria, pensará de outro modo, pois logo verificará que fez cálculo errado e, então, sentimento oposto a esse trará ele para a sua nova existência. É assim que se efetua o progresso e essa a razão por que, na Terra, os homens são desigualmente adiantados. Uns já dispõem de experiência que a outros falta, mas que adquirirão pouco a pouco. Deles depende o acelerar-se-lhes o progresso ou retardar-se indefinidamente." O homem, que ocupa uma posição má, deseja trocá-la o mais depressa possível. Aquele, que se acha persuadido de que as tribulações da vida terrena são conseqüência de suas imperfeições, procurará garantir para si uma nova existência menos penosa e esta idéia o desviará mais depressa da senda do mal do que a do fogo eterno, em que não acredita.', 'rascunho'),
  (196, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Não podendo os Espíritos aperfeiçoar-se, a não ser por meio das tribulações da existência corpórea, segue-se que a vida material seja uma espécie de crisol ou de depurador, por onde têm que passar todos os seres do mundo espírita para alcançarem a perfeição? 96 – Allan Kar dec', 'Sim, é exatamente isso. Eles se melhoram nessas provas, evitando o mal e praticando o bem; porém, somente ao cabo de mais ou menos longo tempo, conforme os esforços que empreguem; somente após muitas encarnações ou depurações sucessivas, atingem a finalidade para que tendem." a) — É o corpo que influi sobre o Espírito para que este se melhore, ou o Espírito que influi sobre o corpo? "Teu Espírito é tudo; teu corpo é simples veste que apodrece: eis tudo." O suco da vide nos oferece um símile material dos diferentes graus da depuração da alma. Ele contém o licor que se chama espírito ou álcool, mas enfraquecido por uma imensidade de matérias estranhas, que lhe alteram a essência. Esta só chega à pureza absoluta depois de múltiplas destilações, em cada uma das quais se despoja de algumas impurezas. O corpo é o alambique em que a alma tem que entrar para se purificar. Às matérias estranhas se assemelha o perispírito, que também se depura, à medida que o Espírito se aproxima da perfeição.', 'rascunho'),
  (197, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Poderá ser tão adiantado quanto o de um adulto o Espírito de uma criança que morreu em tenra idade?', 'Algumas vezes o é muito mais, porquanto pode dar-se que muito mais já tenha vivido e adquirido maior soma de experiência, sobretudo se progrediu." a) — Pode então o Espírito de uma criança ser mais adiantado que o de seu pai? "Isso é muito freqüente. Não o vedes vós mesmos tão amiudadas vezes na Terra?', 'rascunho'),
  (198, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Não tendo podido praticar o mal, o Espírito de uma criança que morreu em tenra idade pertence a alguma das categorias superiores?', 'Se não fez o mal, igualmente não fez o bem e Deus não o isenta das provas que tenha de padecer. Se for um Espírito puro, não o é pelo fato de ter animado apenas uma criança, mas porque já progredira até a pureza.', 'rascunho'),
  (199, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Por que tão freqüentemente a vida se interrompe na infância?', 'A curta duração da vida da criança pode representar, para o Espírito que a animava, o complemento de existência precedentemente interrompida antes do momento em que devera terminar, e sua morte, também não raro, constitui provação ou expiação para os pais." a) — Que sucede ao Espírito de uma criança que morre pequenina? "Recomeça outra existência." Se uma única existência tivesse o homem e se, extinguindo-se-lhe ela, sua sorte ficasse decidida para a eternidade, qual seria o mérito de metade do gênero humano, da que morre na infância, para gozar, sem esforços, da felicidade eterna e com que direito se acharia isenta das condições, às vezes tão duras, a que se vê submetida a outra metade? Semelhante ordem de coisas não corresponderia à justiça de Deus. Com a reencarnação, a igualdade é real para todos. O futuro a todos toca sem exceção e sem favor para quem quer que seja. Os retardatários só de si mesmos se podem queixar. Forçoso é que o homem tenha o merecimento de seus atos, como tem deles a responsabilidade. Aliás, não é racional considerar-se a infância como um estado normal de inocência. Não se vêem crianças dotadas dos piores instintos, numa idade em que ainda nenhuma influência pode ter tido a educação? Algumas não há que parecem trazer do berço a astúcia, a felonia, a perfídia, até pendor para o roubo e para o assassínio, não obstante os bons exemplos que de todos os lados se lhes dão? A lei civil as absolve de seus crimes, porque, diz ela, obraram sem discernimento. Tem razão a lei, porque, de fato, elas obram mais por instinto do que intencionalmente. Donde, porém, provirão instintos tão diversos em crianças da mesma idade, educadas em condições idênticas e sujeitas às mesmas influências? Donde a precoce perversidade, senão da inferioridade do Espírito, uma vez que a educação em nada contribuiu para isso? As que se revelam viciosas, é porque seus Espíritos muito pouco hão progredido. Sofrem então, por efeito dessa falta de progresso, as conseqüências, não dos atos que praticam na infância, mas dos de suas existências anteriores. Assim é que a lei é uma só para todos e que todos são atingidos pela justiça de Deus.', 'rascunho'),
  (200, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Têm sexos os Espíritos?', 'Não como o entendeis, pois que os sexos dependem da organização. Há entre eles amor e simpatia, mas baseados na concordância dos sentimentos.', 'rascunho'),
  (201, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Em nova existência, pode o Espírito que animou o corpo de um homem animar o de uma mulher e vice-versa?', 'Decerto; são os mesmos os Espíritos que animam os homens e as mulheres.', 'rascunho'),
  (202, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Quando errante, que prefere o Espírito: encarnar no corpo de um homem, ou no de uma mulher?', 'Isso pouco lhe importa. O que o guia na escolha são as provas por que haja de passar." Os Espíritos encarnam como homens ou como mulheres, porque não têm sexo. Visto que lhes cumpre progredir em tudo, cada sexo, como cada posição social, lhes proporciona provações e deveres especiais e, com isso, ensejo de ganharem experiência. Aquele que só como homem encarnasse só saberia o que sabem os homens.', 'rascunho'),
  (203, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Transmitem os pais aos filhos uma parcela de suas almas, ou se limitam a lhes dar a vida animal a que, mais tarde, outra alma vem adicionar a vida moral?', 'Dão-lhes apenas a vida animal, pois que a alma é indivisível. Um pai obtuso pode ter filhos inteligentes e vice-versa." 98 – Allan Kar dec', 'rascunho'),
  (204, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Uma vez que temos tido muitas existências, a nossa parentela vai além da que a existência atual nos criou?', 'Não pode ser de outra maneira. A sucessão das existências corporais estabelece entre os Espíritos ligações que remontam às vossas existências anteriores. Daí, muitas vezes, a simpatia que vem a existir entre vós e certos Espíritos que vos parecem estranhos.', 'rascunho'),
  (205, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'A algumas pessoas a doutrina da reencarnação se afigura destruidora dos laços de família, com o fazê-los anteriores à existência atual.', 'Ela os distende; não os destrói. Fundando-se o parentesco em afeições anteriores, menos precários são os laços existentes entre os membros de uma mesma família. Essa doutrina amplia os deveres da fraternidade, porquanto, no vosso vizinho, ou no vosso servo, pode achar-se um Espírito a quem tenhais estado presos pelos laços da consangüinidade." a) — Ela, no entanto, diminui a importância que alguns dão à genealogia, visto que qualquer pode ter tido por pai um Espírito que haja pertencido a outra raça, ou que haja vivido em condição muito diversa. "É exato; mas essa importância assenta no orgulho. Os títulos, a categoria social, a riqueza, eis o que esses tais veneram nos seus antepassados. Um, que coraria de contar, como ascendente, honrado sapateiro, orgulhar-se-ia de descender de um gentil-homem devasso. Digam, porém, o que disserem, ou façam o que fizerem, não obstarão a que as coisas sejam como são, que não foi consultando-lhes a vaidade que Deus formulou as leis da Natureza.', 'rascunho'),
  (206, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Do fato de não haver filiação entre os Espíritos dos descendentes de qualquer família, seguir-se-á que o culto dos avoengos seja ridículo?', 'De modo nenhum. Todo homem deve considerar-se ditoso por pertencer a uma família em que encarnaram Espíritos elevados. Se bem os Espíritos não procedam uns dos outros, nem por isso menos afeição consagram aos que lhes estão ligados pelos elos da família, dado que muitas vezes eles são atraídos para tal ou qual família pela simpatia, ou pelos laços que anteriormente se estabeleceram. Mas, ficai certos de que os vossos antepassados não se honram com o culto que lhes tributais por orgulho. Em vós não se refletem os méritos de que eles gozem, senão na medida dos esforços que empregais por seguir os bons exemplos que vos deram. Somente nestas condições lhes é grata e até mesmo útil a lembrança que deles guardais.', 'rascunho'),
  (207, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Freqüentemente, os pais transmitem aos filhos a parecença física. Transmitirão também alguma parecença moral?', 'Não, que diferentes são as almas ou Espíritos de uns e outros. O corpo deriva do corpo, mas o Espírito não procede do Espírito. Entre os descendentes das raças apenas há consangüinidade." a) — Donde se originam as parecenças morais que costuma haver entre pais e filhos? "É que uns e outros são Espíritos simpáticos, que reciprocamente se atraíram pela analogia dos pendores.', 'rascunho'),
  (208, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Nenhuma influência exercem os Espíritos dos pais sobre o filho depois do nascimento deste?', 'Ao contrário: bem grande influência exercem. Conforme já dissemos, os Espíritos têm que contribuir para o progresso uns dos outros. Pois bem, os Espíritos dos pais têm por missão desenvolver os de seus filhos pela educação. Constitui-lhes isso uma tarefa. Tornar-se-ão culpados, se vierem a falir no seu desempenho.', 'rascunho'),
  (209, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Por que é que de pais bons e virtuosos nascem filhos de natureza perversa? Por outra: por que é que as boas qualidades dos pais nem sempre atraem, por simpatia, um bom Espírito para lhes animar o filho?', 'Não é raro que um mau Espírito peça lhe sejam dados bons pais, na esperança de que seus conselhos o encaminhem por melhor senda e muitas vezes Deus lhe concede o que deseja.', 'rascunho'),
  (210, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IV — Da pluralidade das existências', 'Pelos seus pensamentos e preces podem os pais atrair para o corpo, em formação, do filho um bom Espírito, de preferência a um inferior?', 'Não, mas podem melhorar o Espírito do filho que lhes nasceu e está confiado. Esse o dever deles. Os maus filhos são uma provação para os pais.', 'rascunho')
